// Passages transcribed from the linked public-domain editions.
export default [
  {
    "id": "dhammapada-2",
    "text": "All that we are is the result of what we have thought: it is founded on our thoughts, it is made up of our thoughts. If a man speaks or acts with a pure thought, happiness follows him, like a shadow that never leaves him.",
    "author": "The Dhammapada",
    "source": "Verse 2, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-3",
    "text": "\"He abused me, he beat me, he defeated me, he robbed me,\"--in those who harbour such thoughts hatred will never cease.",
    "author": "The Dhammapada",
    "source": "Verse 3, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-4",
    "text": "\"He abused me, he beat me, he defeated me, he robbed me,\"--in those who do not harbour such thoughts hatred will cease.",
    "author": "The Dhammapada",
    "source": "Verse 4, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-6",
    "text": "The world does not know that we must all come to an end here;--but those who know it, their quarrels cease at once.",
    "author": "The Dhammapada",
    "source": "Verse 6, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-7",
    "text": "He who lives looking for pleasures only, his senses uncontrolled, immoderate in his food, idle, and weak, Mara (the tempter) will certainly overthrow him, as the wind throws down a weak tree.",
    "author": "The Dhammapada",
    "source": "Verse 7, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-8",
    "text": "He who lives without looking for pleasures, his senses well controlled, moderate in his food, faithful and strong, him Mara will certainly not overthrow, any more than the wind throws down a rocky mountain.",
    "author": "The Dhammapada",
    "source": "Verse 8, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-11",
    "text": "They who imagine truth in untruth, and see untruth in truth, never arrive at truth, but follow vain desires.",
    "author": "The Dhammapada",
    "source": "Verse 11, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-12",
    "text": "They who know truth in truth, and untruth in untruth, arrive at truth, and follow true desires.",
    "author": "The Dhammapada",
    "source": "Verse 12, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-13",
    "text": "As rain breaks through an ill-thatched house, passion will break through an unreflecting mind.",
    "author": "The Dhammapada",
    "source": "Verse 13, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-14",
    "text": "As rain does not break through a well-thatched house, passion will not break through a well-reflecting mind.",
    "author": "The Dhammapada",
    "source": "Verse 14, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-19",
    "text": "The thoughtless man, even if he can recite a large portion (of the law), but is not a doer of it, has no share in the priesthood, but is like a cowherd counting the cows of others.",
    "author": "The Dhammapada",
    "source": "Verse 19, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-22",
    "text": "Those who are advanced in earnestness, having understood this clearly, delight in earnestness, and rejoice in the knowledge of the Ariyas (the elect).",
    "author": "The Dhammapada",
    "source": "Verse 22, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-23",
    "text": "These wise people, meditative, steady, always possessed of strong powers, attain to Nirvana, the highest happiness.",
    "author": "The Dhammapada",
    "source": "Verse 23, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-24",
    "text": "If an earnest person has roused himself, if he is not forgetful, if his deeds are pure, if he acts with consideration, if he restrains himself, and lives according to law,--then his glory will increase.",
    "author": "The Dhammapada",
    "source": "Verse 24, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-25",
    "text": "By rousing himself, by earnestness, by restraint and control, the wise man may make for himself an island which no flood can overwhelm.",
    "author": "The Dhammapada",
    "source": "Verse 25, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-27",
    "text": "Follow not after vanity, nor after the enjoyment of love and lust! He who is earnest and meditative, obtains ample joy.",
    "author": "The Dhammapada",
    "source": "Verse 27, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-28",
    "text": "When the learned man drives away vanity by earnestness, he, the wise, climbing the terraced heights of wisdom, looks down upon the fools, serene he looks upon the toiling crowd, as one that stands on a mountain looks down upon them that stand upon the plain.",
    "author": "The Dhammapada",
    "source": "Verse 28, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-29",
    "text": "Earnest among the thoughtless, awake among the sleepers, the wise man advances like a racer, leaving behind the hack.",
    "author": "The Dhammapada",
    "source": "Verse 29, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-30",
    "text": "By earnestness did Maghavan (Indra) rise to the lordship of the gods. People praise earnestness; thoughtlessness is always blamed.",
    "author": "The Dhammapada",
    "source": "Verse 30, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-31",
    "text": "A Bhikshu (mendicant) who delights in earnestness, who looks with fear on thoughtlessness, moves about like fire, burning all his fetters, small or large.",
    "author": "The Dhammapada",
    "source": "Verse 31, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-32",
    "text": "A Bhikshu (mendicant) who delights in reflection, who looks with fear on thoughtlessness, cannot fall away (from his perfect state)--he is close upon Nirvana.",
    "author": "The Dhammapada",
    "source": "Verse 32, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-33",
    "text": "As a fletcher makes straight his arrow, a wise man makes straight his trembling and unsteady thought, which is difficult to guard, difficult to hold back.",
    "author": "The Dhammapada",
    "source": "Verse 33, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-34",
    "text": "As a fish taken from his watery home and thrown on dry ground, our thought trembles all over in order to escape the dominion of Mara (the tempter).",
    "author": "The Dhammapada",
    "source": "Verse 34, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-35",
    "text": "It is good to tame the mind, which is difficult to hold in and flighty, rushing wherever it listeth; a tamed mind brings happiness.",
    "author": "The Dhammapada",
    "source": "Verse 35, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-36",
    "text": "Let the wise man guard his thoughts, for they are difficult to perceive, very artful, and they rush wherever they list: thoughts well guarded bring happiness.",
    "author": "The Dhammapada",
    "source": "Verse 36, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-37",
    "text": "Those who bridle their mind which travels far, moves about alone, is without a body, and hides in the chamber (of the heart), will be free from the bonds of Mara (the tempter).",
    "author": "The Dhammapada",
    "source": "Verse 37, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-38",
    "text": "If a man's thoughts are unsteady, if he does not know the true law, if his peace of mind is troubled, his knowledge will never be perfect.",
    "author": "The Dhammapada",
    "source": "Verse 38, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-40",
    "text": "Knowing that this body is (fragile) like a jar, and making this thought firm like a fortress, one should attack Mara (the tempter) with the weapon of knowledge, one should watch him when conquered, and should never rest.",
    "author": "The Dhammapada",
    "source": "Verse 40, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-41",
    "text": "Before long, alas! this body will lie on the earth, despised, without understanding, like a useless log.",
    "author": "The Dhammapada",
    "source": "Verse 41, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-42",
    "text": "Whatever a hater may do to a hater, or an enemy to an enemy, a wrongly-directed mind will do us greater mischief.",
    "author": "The Dhammapada",
    "source": "Verse 42, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-44",
    "text": "Who shall overcome this earth, and the world of Yama (the lord of the departed), and the world of the gods? Who shall find out the plainly shown path of virtue, as a clever man finds out the (right) flower?",
    "author": "The Dhammapada",
    "source": "Verse 44, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-45",
    "text": "The disciple will overcome the earth, and the world of Yama, and the world of the gods. The disciple will find out the plainly shown path of virtue, as a clever man finds out the (right) flower.",
    "author": "The Dhammapada",
    "source": "Verse 45, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-49",
    "text": "As the bee collects nectar and departs without injuring the flower, or its colour or scent, so let a sage dwell in his village.",
    "author": "The Dhammapada",
    "source": "Verse 49, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-50",
    "text": "Not the perversities of others, not their sins of commission or omission, but his own misdeeds and negligences should a sage take notice of.",
    "author": "The Dhammapada",
    "source": "Verse 50, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-51",
    "text": "Like a beautiful flower, full of colour, but without scent, are the fine but fruitless words of him who does not act accordingly.",
    "author": "The Dhammapada",
    "source": "Verse 51, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-52",
    "text": "But, like a beautiful flower, full of colour and full of scent, are the fine and fruitful words of him who acts accordingly.",
    "author": "The Dhammapada",
    "source": "Verse 52, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-53",
    "text": "As many kinds of wreaths can be made from a heap of flowers, so many good things may be achieved by a mortal when once he is born.",
    "author": "The Dhammapada",
    "source": "Verse 53, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-54",
    "text": "The scent of flowers does not travel against the wind, nor (that of) sandal-wood, or of Tagara and Mallika flowers; but the odour of good people travels even against the wind; a good man pervades every place.",
    "author": "The Dhammapada",
    "source": "Verse 54, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-55",
    "text": "Sandal-wood or Tagara, a lotus-flower, or a Vassiki, among these sorts of perfumes, the perfume of virtue is unsurpassed.",
    "author": "The Dhammapada",
    "source": "Verse 55, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-56",
    "text": "Mean is the scent that comes from Tagara and sandal-wood;--the perfume of those who possess virtue rises up to the gods as the highest.",
    "author": "The Dhammapada",
    "source": "Verse 56, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-57",
    "text": "Of the people who possess these virtues, who live without thoughtlessness, and who are emancipated through true knowledge, Mara, the tempter, never finds the way.",
    "author": "The Dhammapada",
    "source": "Verse 57, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-60",
    "text": "Long is the night to him who is awake; long is a mile to him who is tired; long is life to the foolish who do not know the true law.",
    "author": "The Dhammapada",
    "source": "Verse 60, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-65",
    "text": "If an intelligent man be associated for one minute only with a wise man, he will soon perceive the truth, as the tongue perceives the taste of soup.",
    "author": "The Dhammapada",
    "source": "Verse 65, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-67",
    "text": "That deed is not well done of which a man must repent, and the reward of which he receives crying and with a tearful face.",
    "author": "The Dhammapada",
    "source": "Verse 67, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-68",
    "text": "No, that deed is well done of which a man does not repent, and the reward of which he receives gladly and cheerfully.",
    "author": "The Dhammapada",
    "source": "Verse 68, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-76",
    "text": "If you see an intelligent man who tells you where true treasures are to be found, who shows what is to be avoided, and administers reproofs, follow that wise man; it will be better, not worse, for those who follow him.",
    "author": "The Dhammapada",
    "source": "Verse 76, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-77",
    "text": "Let him admonish, let him teach, let him forbid what is improper!- -he will be beloved of the good, by the bad he will be hated.",
    "author": "The Dhammapada",
    "source": "Verse 77, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-79",
    "text": "He who drinks in the law lives happily with a serene mind: the sage rejoices always in the law, as preached by the elect (Ariyas).",
    "author": "The Dhammapada",
    "source": "Verse 79, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-80",
    "text": "Well-makers lead the water (wherever they like); fletchers bend the arrow; carpenters bend a log of wood; wise people fashion themselves.",
    "author": "The Dhammapada",
    "source": "Verse 80, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-81",
    "text": "As a solid rock is not shaken by the wind, wise people falter not amidst blame and praise.",
    "author": "The Dhammapada",
    "source": "Verse 81, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-82",
    "text": "Wise people, after they have listened to the laws, become serene, like a deep, smooth, and still lake.",
    "author": "The Dhammapada",
    "source": "Verse 82, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-83",
    "text": "Good people walk on whatever befall, the good do not prattle, longing for pleasure; whether touched by happiness or sorrow wise people never appear elated or depressed.",
    "author": "The Dhammapada",
    "source": "Verse 83, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-85",
    "text": "Few are there among men who arrive at the other shore (become Arhats); the other people here run up and down the shore.",
    "author": "The Dhammapada",
    "source": "Verse 85, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-89",
    "text": "Those whose mind is well grounded in the (seven) elements of knowledge, who without clinging to anything, rejoice in freedom from attachment, whose appetites have been conquered, and who are full of light, are free (even) in this world.",
    "author": "The Dhammapada",
    "source": "Verse 89, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-90",
    "text": "There is no suffering for him who has finished his journey, and abandoned grief, who has freed himself on all sides, and thrown off all fetters.",
    "author": "The Dhammapada",
    "source": "Verse 90, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-91",
    "text": "They depart with their thoughts well-collected, they are not happy in their abode; like swans who have left their lake, they leave their house and home.",
    "author": "The Dhammapada",
    "source": "Verse 91, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-92",
    "text": "Men who have no riches, who live on recognised food, who have perceived void and unconditioned freedom (Nirvana), their path is difficult to understand, like that of birds in the air.",
    "author": "The Dhammapada",
    "source": "Verse 92, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-93",
    "text": "He whose appetites are stilled, who is not absorbed in enjoyment, who has perceived void and unconditioned freedom (Nirvana), his path is difficult to understand, like that of birds in the air.",
    "author": "The Dhammapada",
    "source": "Verse 93, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-94",
    "text": "The gods even envy him whose senses, like horses well broken in by the driver, have been subdued, who is free from pride, and free from appetites.",
    "author": "The Dhammapada",
    "source": "Verse 94, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-95",
    "text": "Such a one who does his duty is tolerant like the earth, like Indra's bolt; he is like a lake without mud; no new births are in store for him.",
    "author": "The Dhammapada",
    "source": "Verse 95, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-96",
    "text": "His thought is quiet, quiet are his word and deed, when he has obtained freedom by true knowledge, when he has thus become a quiet man.",
    "author": "The Dhammapada",
    "source": "Verse 96, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-97",
    "text": "The man who is free from credulity, but knows the uncreated, who has cut all ties, removed all temptations, renounced all desires, he is the greatest of men.",
    "author": "The Dhammapada",
    "source": "Verse 97, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-98",
    "text": "In a hamlet or in a forest, in the deep water or on the dry land, wherever venerable persons (Arhanta) dwell, that place is delightful.",
    "author": "The Dhammapada",
    "source": "Verse 98, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-99",
    "text": "Forests are delightful; where the world finds no delight, there the passionless will find delight, for they look not for pleasures.",
    "author": "The Dhammapada",
    "source": "Verse 99, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-100",
    "text": "Even though a speech be a thousand (of words), but made up of senseless words, one word of sense is better, which if a man hears, he becomes quiet.",
    "author": "The Dhammapada",
    "source": "Verse 100, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-101",
    "text": "Even though a Gatha (poem) be a thousand (of words), but made up of senseless words, one word of a Gatha is better, which if a man hears, he becomes quiet.",
    "author": "The Dhammapada",
    "source": "Verse 101, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-102",
    "text": "Though a man recite a hundred Gathas made up of senseless words, one word of the law is better, which if a man hears, he becomes quiet.",
    "author": "The Dhammapada",
    "source": "Verse 102, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-103",
    "text": "If one man conquer in battle a thousand times thousand men, and if another conquer himself, he is the greatest of conquerors.",
    "author": "The Dhammapada",
    "source": "Verse 103, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-106",
    "text": "If a man for a hundred years sacrifice month after month with a thousand, and if he but for one moment pay homage to a man whose soul is grounded (in true knowledge), better is that homage than sacrifice for a hundred years.",
    "author": "The Dhammapada",
    "source": "Verse 106, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-107",
    "text": "If a man for a hundred years worship Agni (fire) in the forest, and if he but for one moment pay homage to a man whose soul is grounded (in true knowledge), better is that homage than sacrifice for a hundred years.",
    "author": "The Dhammapada",
    "source": "Verse 107, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-108",
    "text": "Whatever a man sacrifice in this world as an offering or as an oblation for a whole year in order to gain merit, the whole of it is not worth a quarter (a farthing); reverence shown to the righteous is better.",
    "author": "The Dhammapada",
    "source": "Verse 108, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-109",
    "text": "He who always greets and constantly reveres the aged, four things will increase to him, viz. life, beauty, happiness, power.",
    "author": "The Dhammapada",
    "source": "Verse 109, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-111",
    "text": "And he who lives a hundred years, ignorant and unrestrained, a life of one day is better if a man is wise and reflecting.",
    "author": "The Dhammapada",
    "source": "Verse 111, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-112",
    "text": "And he who lives a hundred years, idle and weak, a life of one day is better if a man has attained firm strength.",
    "author": "The Dhammapada",
    "source": "Verse 112, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-113",
    "text": "And he who lives a hundred years, not seeing beginning and end, a life of one day is better if a man sees beginning and end.",
    "author": "The Dhammapada",
    "source": "Verse 113, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-114",
    "text": "And he who lives a hundred years, not seeing the immortal place, a life of one day is better if a man sees the immortal place.",
    "author": "The Dhammapada",
    "source": "Verse 114, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-115",
    "text": "And he who lives a hundred years, not seeing the highest law, a life of one day is better if a man sees the highest law.",
    "author": "The Dhammapada",
    "source": "Verse 115, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-118",
    "text": "If a man does what is good, let him do it again; let him delight in it: happiness is the outcome of good.",
    "author": "The Dhammapada",
    "source": "Verse 118, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-122",
    "text": "Let no man think lightly of good, saying in his heart, It will not come nigh unto me. Even by the falling of water-drops a water-pot is filled; the wise man becomes full of good, even if he gather it little by little.",
    "author": "The Dhammapada",
    "source": "Verse 122, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-133",
    "text": "Do not speak harshly to anybody; those who are spoken to will answer thee in the same way. Angry speech is painful, blows for blows will touch thee.",
    "author": "The Dhammapada",
    "source": "Verse 133, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-134",
    "text": "If, like a shattered metal plate (gong), thou utter not, then thou hast reached Nirvana; contention is not known to thee.",
    "author": "The Dhammapada",
    "source": "Verse 134, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-137",
    "text": "He who inflicts pain on innocent and harmless persons, will soon come to one of these ten states:",
    "author": "The Dhammapada",
    "source": "Verse 137, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-138",
    "text": "He will have cruel suffering, loss, injury of the body, heavy affliction, or loss of mind,",
    "author": "The Dhammapada",
    "source": "Verse 138, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-139",
    "text": "Or a misfortune coming from the king, or a fearful accusation, or loss of relations, or destruction of treasures,",
    "author": "The Dhammapada",
    "source": "Verse 139, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-141",
    "text": "Not nakedness, not platted hair, not dirt, not fasting, or lying on the earth, not rubbing with dust, not sitting motionless, can purify a mortal who has not overcome desires.",
    "author": "The Dhammapada",
    "source": "Verse 141, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-143",
    "text": "Is there in this world any man so restrained by humility that he does not mind reproof, as a well-trained horse the whip?",
    "author": "The Dhammapada",
    "source": "Verse 143, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-144",
    "text": "Like a well-trained horse when touched by the whip, be ye active and lively, and by faith, by virtue, by energy, by meditation, by discernment of the law you will overcome this great pain (of reproof), perfect in knowledge and in behaviour, and never forgetful.",
    "author": "The Dhammapada",
    "source": "Verse 144, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-145",
    "text": "Well-makers lead the water (wherever they like); fletchers bend the arrow; carpenters bend a log of wood; good people fashion themselves.",
    "author": "The Dhammapada",
    "source": "Verse 145, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-146",
    "text": "How is there laughter, how is there joy, as this world is always burning? Why do you not seek a light, ye who are surrounded by darkness?",
    "author": "The Dhammapada",
    "source": "Verse 146, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-147",
    "text": "Look at this dressed-up lump, covered with wounds, joined together, sickly, full of many thoughts, which has no strength, no hold!",
    "author": "The Dhammapada",
    "source": "Verse 147, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-149",
    "text": "Those white bones, like gourds thrown away in the autumn, what pleasure is there in looking at them?",
    "author": "The Dhammapada",
    "source": "Verse 149, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-151",
    "text": "The brilliant chariots of kings are destroyed, the body also approaches destruction, but the virtue of good people never approaches destruction,--thus do the good say to the good.",
    "author": "The Dhammapada",
    "source": "Verse 151, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-155",
    "text": "Men who have not observed proper discipline, and have not gained treasure in their youth, perish like old herons in a lake without fish.",
    "author": "The Dhammapada",
    "source": "Verse 155, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-156",
    "text": "Men who have not observed proper discipline, and have not gained treasure in their youth, lie, like broken bows, sighing after the past.",
    "author": "The Dhammapada",
    "source": "Verse 156, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-157",
    "text": "If a man hold himself dear, let him watch himself carefully; during one at least out of the three watches a wise man should be watchful.",
    "author": "The Dhammapada",
    "source": "Verse 157, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-158",
    "text": "Let each man direct himself first to what is proper, then let him teach others; thus a wise man will not suffer.",
    "author": "The Dhammapada",
    "source": "Verse 158, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-159",
    "text": "If a man make himself as he teaches others to be, then, being himself well subdued, he may subdue (others); one's own self is indeed difficult to subdue.",
    "author": "The Dhammapada",
    "source": "Verse 159, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-160",
    "text": "Self is the lord of self, who else could be the lord? With self well subdued, a man finds a lord such as few can find.",
    "author": "The Dhammapada",
    "source": "Verse 160, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-162",
    "text": "He whose wickedness is very great brings himself down to that state where his enemy wishes him to be, as a creeper does with the tree which it surrounds.",
    "author": "The Dhammapada",
    "source": "Verse 162, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-163",
    "text": "Bad deeds, and deeds hurtful to ourselves, are easy to do; what is beneficial and good, that is very difficult to do.",
    "author": "The Dhammapada",
    "source": "Verse 163, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-166",
    "text": "Let no one forget his own duty for the sake of another's, however great; let a man, after he has discerned his own duty, be always attentive to his duty.",
    "author": "The Dhammapada",
    "source": "Verse 166, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-171",
    "text": "Come, look at this glittering world, like unto a royal chariot; the foolish are immersed in it, but the wise do not touch it.",
    "author": "The Dhammapada",
    "source": "Verse 171, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-172",
    "text": "He who formerly was reckless and afterwards became sober, brightens up this world, like the moon when freed from clouds.",
    "author": "The Dhammapada",
    "source": "Verse 172, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-174",
    "text": "This world is dark, few only can see here; a few only go to heaven, like birds escaped from the net.",
    "author": "The Dhammapada",
    "source": "Verse 174, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-175",
    "text": "The swans go on the path of the sun, they go through the ether by means of their miraculous power; the wise are led out of this world, when they have conquered Mara and his train.",
    "author": "The Dhammapada",
    "source": "Verse 175, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-177",
    "text": "The uncharitable do not go to the world of the gods; fools only do not praise liberality; a wise man rejoices in liberality, and through it becomes blessed in the other world.",
    "author": "The Dhammapada",
    "source": "Verse 177, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-178",
    "text": "Better than sovereignty over the earth, better than going to heaven, better than lordship over all worlds, is the reward of the first step in holiness.",
    "author": "The Dhammapada",
    "source": "Verse 178, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-179",
    "text": "He whose conquest is not conquered again, into whose conquest no one in this world enters, by what track can you lead him, the Awakened, the Omniscient, the trackless?",
    "author": "The Dhammapada",
    "source": "Verse 179, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-180",
    "text": "He whom no desire with its snares and poisons can lead astray, by what track can you lead him, the Awakened, the Omniscient, the trackless?",
    "author": "The Dhammapada",
    "source": "Verse 180, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-181",
    "text": "Even the gods envy those who are awakened and not forgetful, who are given to meditation, who are wise, and who delight in the repose of retirement (from the world).",
    "author": "The Dhammapada",
    "source": "Verse 181, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-182",
    "text": "Difficult (to obtain) is the conception of men, difficult is the life of mortals, difficult is the hearing of the True Law, difficult is the birth of the Awakened (the attainment of Buddhahood).",
    "author": "The Dhammapada",
    "source": "Verse 182, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-184",
    "text": "The Awakened call patience the highest penance, long-suffering the highest Nirvana; for he is not an anchorite (pravragita) who strikes others, he is not an ascetic (sramana) who insults others.",
    "author": "The Dhammapada",
    "source": "Verse 184, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-185",
    "text": "Not to blame, not to strike, to live restrained under the law, to be moderate in eating, to sleep and sit alone, and to dwell on the highest thoughts,--this is the teaching of the Awakened.",
    "author": "The Dhammapada",
    "source": "Verse 185, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-186",
    "text": "There is no satisfying lusts, even by a shower of gold pieces; he who knows that lusts have a short taste and cause pain, he is wise;",
    "author": "The Dhammapada",
    "source": "Verse 186, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-187",
    "text": "Even in heavenly pleasures he finds no satisfaction, the disciple who is fully awakened delights only in the destruction of all desires.",
    "author": "The Dhammapada",
    "source": "Verse 187, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-188",
    "text": "Men, driven by fear, go to many a refuge, to mountains and forests, to groves and sacred trees.",
    "author": "The Dhammapada",
    "source": "Verse 188, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-189",
    "text": "But that is not a safe refuge, that is not the best refuge; a man is not delivered from all pains after having gone to that refuge.",
    "author": "The Dhammapada",
    "source": "Verse 189, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-191",
    "text": "Viz. pain, the origin of pain, the destruction of pain, and the eightfold holy way that leads to the quieting of pain;--",
    "author": "The Dhammapada",
    "source": "Verse 191, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-192",
    "text": "That is the safe refuge, that is the best refuge; having gone to that refuge, a man is delivered from all pain.",
    "author": "The Dhammapada",
    "source": "Verse 192, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-194",
    "text": "Happy is the arising of the awakened, happy is the teaching of the True Law, happy is peace in the church, happy is the devotion of those who are at peace.",
    "author": "The Dhammapada",
    "source": "Verse 194, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-197",
    "text": "Let us live happily then, not hating those who hate us! among men who hate us let us dwell free from hatred!",
    "author": "The Dhammapada",
    "source": "Verse 197, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-198",
    "text": "Let us live happily then, free from ailments among the ailing! among men who are ailing let us dwell free from ailments!",
    "author": "The Dhammapada",
    "source": "Verse 198, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-199",
    "text": "Let us live happily then, free from greed among the greedy! among men who are greedy let us dwell free from greed!",
    "author": "The Dhammapada",
    "source": "Verse 199, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-200",
    "text": "Let us live happily then, though we call nothing our own! We shall be like the bright gods, feeding on happiness!",
    "author": "The Dhammapada",
    "source": "Verse 200, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-201",
    "text": "Victory breeds hatred, for the conquered is unhappy. He who has given up both victory and defeat, he, the contented, is happy.",
    "author": "The Dhammapada",
    "source": "Verse 201, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-202",
    "text": "There is no fire like passion; there is no losing throw like hatred; there is no pain like this body; there is no happiness higher than rest.",
    "author": "The Dhammapada",
    "source": "Verse 202, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-203",
    "text": "Hunger is the worst of diseases, the body the greatest of pains; if one knows this truly, that is Nirvana, the highest happiness.",
    "author": "The Dhammapada",
    "source": "Verse 203, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-204",
    "text": "Health is the greatest of gifts, contentedness the best riches; trust is the best of relationships, Nirvana the highest happiness.",
    "author": "The Dhammapada",
    "source": "Verse 204, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-206",
    "text": "The sight of the elect (Arya) is good, to live with them is always happiness; if a man does not see fools, he will be truly happy.",
    "author": "The Dhammapada",
    "source": "Verse 206, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-207",
    "text": "He who walks in the company of fools suffers a long way; company with fools, as with an enemy, is always painful; company with the wise is pleasure, like meeting with kinsfolk.",
    "author": "The Dhammapada",
    "source": "Verse 207, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-208",
    "text": "Therefore, one ought to follow the wise, the intelligent, the learned, the much enduring, the dutiful, the elect; one ought to follow a good and wise man, as the moon follows the path of the stars.",
    "author": "The Dhammapada",
    "source": "Verse 208, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-209",
    "text": "He who gives himself to vanity, and does not give himself to meditation, forgetting the real aim (of life) and grasping at pleasure, will in time envy him who has exerted himself in meditation.",
    "author": "The Dhammapada",
    "source": "Verse 209, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-210",
    "text": "Let no man ever look for what is pleasant, or what is unpleasant. Not to see what is pleasant is pain, and it is pain to see what is unpleasant.",
    "author": "The Dhammapada",
    "source": "Verse 210, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-212",
    "text": "From pleasure comes grief, from pleasure comes fear; he who is free from pleasure knows neither grief nor fear.",
    "author": "The Dhammapada",
    "source": "Verse 212, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-213",
    "text": "From affection comes grief, from affection comes fear; he who is free from affection knows neither grief nor fear.",
    "author": "The Dhammapada",
    "source": "Verse 213, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-214",
    "text": "From lust comes grief, from lust comes fear; he who is free from lust knows neither grief nor fear.",
    "author": "The Dhammapada",
    "source": "Verse 214, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-215",
    "text": "From love comes grief, from love comes fear; he who is free from love knows neither grief nor fear.",
    "author": "The Dhammapada",
    "source": "Verse 215, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-216",
    "text": "From greed comes grief, from greed comes fear; he who is free from greed knows neither grief nor fear.",
    "author": "The Dhammapada",
    "source": "Verse 216, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-217",
    "text": "He who possesses virtue and intelligence, who is just, speaks the truth, and does what is his own business, him the world will hold dear.",
    "author": "The Dhammapada",
    "source": "Verse 217, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-218",
    "text": "He in whom a desire for the Ineffable (Nirvana) has sprung up, who is satisfied in his mind, and whose thoughts are not bewildered by love, he is called urdhvamsrotas (carried upwards by the stream).",
    "author": "The Dhammapada",
    "source": "Verse 218, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-219",
    "text": "Kinsmen, friends, and lovers salute a man who has been long away, and returns safe from afar.",
    "author": "The Dhammapada",
    "source": "Verse 219, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-220",
    "text": "In like manner his good works receive him who has done good, and has gone from this world to the other;--as kinsmen receive a friend on his return.",
    "author": "The Dhammapada",
    "source": "Verse 220, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-221",
    "text": "Let a man leave anger, let him forsake pride, let him overcome all bondage! No sufferings befall the man who is not attached to name and form, and who calls nothing his own.",
    "author": "The Dhammapada",
    "source": "Verse 221, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-222",
    "text": "He who holds back rising anger like a rolling chariot, him I call a real driver; other people are but holding the reins.",
    "author": "The Dhammapada",
    "source": "Verse 222, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-224",
    "text": "Speak the truth, do not yield to anger; give, if thou art asked for little; by these three steps thou wilt go near the gods.",
    "author": "The Dhammapada",
    "source": "Verse 224, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-225",
    "text": "The sages who injure nobody, and who always control their body, they will go to the unchangeable place (Nirvana), where, if they have gone, they will suffer no more.",
    "author": "The Dhammapada",
    "source": "Verse 225, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-226",
    "text": "Those who are ever watchful, who study day and night, and who strive after Nirvana, their passions will come to an end.",
    "author": "The Dhammapada",
    "source": "Verse 226, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-227",
    "text": "This is an old saying, O Atula, this is not only of to-day: `They blame him who sits silent, they blame him who speaks much, they also blame him who says little; there is no one on earth who is not blamed.'",
    "author": "The Dhammapada",
    "source": "Verse 227, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-228",
    "text": "There never was, there never will be, nor is there now, a man who is always blamed, or a man who is always praised.",
    "author": "The Dhammapada",
    "source": "Verse 228, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-231",
    "text": "Beware of bodily anger, and control thy body! Leave the sins of the body, and with thy body practise virtue!",
    "author": "The Dhammapada",
    "source": "Verse 231, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-232",
    "text": "Beware of the anger of the tongue, and control thy tongue! Leave the sins of the tongue, and practise virtue with thy tongue!",
    "author": "The Dhammapada",
    "source": "Verse 232, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-233",
    "text": "Beware of the anger of the mind, and control thy mind! Leave the sins of the mind, and practise virtue with thy mind!",
    "author": "The Dhammapada",
    "source": "Verse 233, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-234",
    "text": "The wise who control their body, who control their tongue, the wise who control their mind, are indeed well controlled.",
    "author": "The Dhammapada",
    "source": "Verse 234, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-238",
    "text": "Make thyself an island, work hard, be wise! When thy impurities are blown away, and thou art free from guilt, thou wilt not enter again into birth and decay.",
    "author": "The Dhammapada",
    "source": "Verse 238, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-239",
    "text": "Let a wise man blow off the impurities of his self, as a smith blows off the impurities of silver one by one, little by little, and from time to time.",
    "author": "The Dhammapada",
    "source": "Verse 239, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-241",
    "text": "The taint of prayers is non-repetition; the taint of houses, non- repair; the taint of the body is sloth; the taint of a watchman, thoughtlessness.",
    "author": "The Dhammapada",
    "source": "Verse 241, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-243",
    "text": "But there is a taint worse than all taints,--ignorance is the greatest taint. O mendicants! throw off that taint, and become taintless!",
    "author": "The Dhammapada",
    "source": "Verse 243, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-244",
    "text": "Life is easy to live for a man who is without shame, a crow hero, a mischief-maker, an insulting, bold, and wretched fellow.",
    "author": "The Dhammapada",
    "source": "Verse 244, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-245",
    "text": "But life is hard to live for a modest man, who always looks for what is pure, who is disinterested, quiet, spotless, and intelligent.",
    "author": "The Dhammapada",
    "source": "Verse 245, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-247",
    "text": "And the man who gives himself to drinking intoxicating liquors, he, even in this world, digs up his own root.",
    "author": "The Dhammapada",
    "source": "Verse 247, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-248",
    "text": "O man, know this, that the unrestrained are in a bad state; take care that greediness and vice do not bring thee to grief for a long time!",
    "author": "The Dhammapada",
    "source": "Verse 248, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-249",
    "text": "The world gives according to their faith or according to their pleasure: if a man frets about the food and the drink given to others, he will find no rest either by day or by night.",
    "author": "The Dhammapada",
    "source": "Verse 249, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-250",
    "text": "He in whom that feeling is destroyed, and taken out with the very root, finds rest by day and by night.",
    "author": "The Dhammapada",
    "source": "Verse 250, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-251",
    "text": "There is no fire like passion, there is no shark like hatred, there is no snare like folly, there is no torrent like greed.",
    "author": "The Dhammapada",
    "source": "Verse 251, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-253",
    "text": "If a man looks after the faults of others, and is always inclined to be offended, his own passions will grow, and he is far from the destruction of passions.",
    "author": "The Dhammapada",
    "source": "Verse 253, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-254",
    "text": "There is no path through the air, a man is not a Samana by outward acts. The world delights in vanity, the Tathagatas (the Buddhas) are free from vanity.",
    "author": "The Dhammapada",
    "source": "Verse 254, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-258",
    "text": "A man is not learned because he talks much; he who is patient, free from hatred and fear, he is called learned.",
    "author": "The Dhammapada",
    "source": "Verse 258, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-259",
    "text": "A man is not a supporter of the law because he talks much; even if a man has learnt little, but sees the law bodily, he is a supporter of the law, a man who never neglects the law.",
    "author": "The Dhammapada",
    "source": "Verse 259, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-260",
    "text": "A man is not an elder because his head is grey; his age may be ripe, but he is called `Old-in-vain.'",
    "author": "The Dhammapada",
    "source": "Verse 260, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-262",
    "text": "An envious greedy, dishonest man does not become respectable by means of much talking only, or by the beauty of his complexion.",
    "author": "The Dhammapada",
    "source": "Verse 262, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-263",
    "text": "He in whom all this is destroyed, and taken out with the very root, he, when freed from hatred and wise, is called respectable.",
    "author": "The Dhammapada",
    "source": "Verse 263, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-264",
    "text": "Not by tonsure does an undisciplined man who speaks falsehood become a Samana; can a man be a Samana who is still held captive by desire and greediness?",
    "author": "The Dhammapada",
    "source": "Verse 264, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-266",
    "text": "A man is not a mendicant (Bhikshu) simply because he asks others for alms; he who adopts the whole law is a Bhikshu, not he who only begs.",
    "author": "The Dhammapada",
    "source": "Verse 266, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-270",
    "text": "A man is not an elect (Ariya) because he injures living creatures; because he has pity on all living creatures, therefore is a man called Ariya.",
    "author": "The Dhammapada",
    "source": "Verse 270, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-273",
    "text": "The best of ways is the eightfold; the best of truths the four words; the best of virtues passionlessness; the best of men he who has eyes to see.",
    "author": "The Dhammapada",
    "source": "Verse 273, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-274",
    "text": "This is the way, there is no other that leads to the purifying of intelligence. Go on this way! Everything else is the deceit of Mara (the tempter).",
    "author": "The Dhammapada",
    "source": "Verse 274, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-276",
    "text": "You yourself must make an effort. The Tathagatas (Buddhas) are only preachers. The thoughtful who enter the way are freed from the bondage of Mara.",
    "author": "The Dhammapada",
    "source": "Verse 276, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-277",
    "text": "`All created things perish,' he who knows and sees this becomes passive in pain; this is the way to purity.",
    "author": "The Dhammapada",
    "source": "Verse 277, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-278",
    "text": "`All created things are grief and pain,' he who knows and sees this becomes passive in pain; this is the way that leads to purity.",
    "author": "The Dhammapada",
    "source": "Verse 278, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-279",
    "text": "`All forms are unreal,' he who knows and sees this becomes passive in pain; this is the way that leads to purity.",
    "author": "The Dhammapada",
    "source": "Verse 279, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-280",
    "text": "He who does not rouse himself when it is time to rise, who, though young and strong, is full of sloth, whose will and thought are weak, that lazy and idle man will never find the way to knowledge.",
    "author": "The Dhammapada",
    "source": "Verse 280, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-281",
    "text": "Watching his speech, well restrained in mind, let a man never commit any wrong with his body! Let a man but keep these three roads of action clear, and he will achieve the way which is taught by the wise.",
    "author": "The Dhammapada",
    "source": "Verse 281, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-282",
    "text": "Through zeal knowledge is gotten, through lack of zeal knowledge is lost; let a man who knows this double path of gain and loss thus place himself that knowledge may grow.",
    "author": "The Dhammapada",
    "source": "Verse 282, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-283",
    "text": "Cut down the whole forest (of lust), not a tree only! Danger comes out of the forest (of lust). When you have cut down both the forest (of lust) and its undergrowth, then, Bhikshus, you will be rid of the forest and free!",
    "author": "The Dhammapada",
    "source": "Verse 283, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-289",
    "text": "A wise and good man who knows the meaning of this, should quickly clear the way that leads to Nirvana.",
    "author": "The Dhammapada",
    "source": "Verse 289, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-290",
    "text": "If by leaving a small pleasure one sees a great pleasure, let a wise man leave the small pleasure, and look to the great.",
    "author": "The Dhammapada",
    "source": "Verse 290, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-291",
    "text": "He who, by causing pain to others, wishes to obtain pleasure for himself, he, entangled in the bonds of hatred, will never be free from hatred.",
    "author": "The Dhammapada",
    "source": "Verse 291, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-292",
    "text": "What ought to be done is neglected, what ought not to be done is done; the desires of unruly, thoughtless people are always increasing.",
    "author": "The Dhammapada",
    "source": "Verse 292, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-293",
    "text": "But they whose whole watchfulness is always directed to their body, who do not follow what ought not to be done, and who steadfastly do what ought to be done, the desires of such watchful and wise people will come to an end.",
    "author": "The Dhammapada",
    "source": "Verse 293, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-297",
    "text": "The disciples of Gotama are always well awake, and their thoughts day and night are always set on the law.",
    "author": "The Dhammapada",
    "source": "Verse 297, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-298",
    "text": "The disciples of Gotama are always well awake, and their thoughts day and night are always set on the church.",
    "author": "The Dhammapada",
    "source": "Verse 298, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-299",
    "text": "The disciples of Gotama are always well awake, and their thoughts day and night are always set on their body.",
    "author": "The Dhammapada",
    "source": "Verse 299, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-300",
    "text": "The disciples of Gotama are always well awake, and their mind day and night always delights in compassion.",
    "author": "The Dhammapada",
    "source": "Verse 300, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-301",
    "text": "The disciples of Gotama are always well awake, and their mind day and night always delights in meditation.",
    "author": "The Dhammapada",
    "source": "Verse 301, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-304",
    "text": "Good people shine from afar, like the snowy mountains; bad people are not seen, like arrows shot by night.",
    "author": "The Dhammapada",
    "source": "Verse 304, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-305",
    "text": "He alone who, without ceasing, practises the duty of sitting alone and sleeping alone, he, subduing himself, will rejoice in the destruction of all desires alone, as if living in a forest.",
    "author": "The Dhammapada",
    "source": "Verse 305, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-308",
    "text": "Better it would be to swallow a heated iron ball, like flaring fire, than that a bad unrestrained fellow should live on the charity of the land.",
    "author": "The Dhammapada",
    "source": "Verse 308, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-312",
    "text": "An act carelessly performed, a broken vow, and hesitating obedience to discipline, all this brings no great reward.",
    "author": "The Dhammapada",
    "source": "Verse 312, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-313",
    "text": "If anything is to be done, let a man do it, let him attack it vigorously! A careless pilgrim only scatters the dust of his passions more widely.",
    "author": "The Dhammapada",
    "source": "Verse 313, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-319",
    "text": "They who know what is forbidden as forbidden, and what is not forbidden as not forbidden, such men, embracing the true doctrine, enter the good path.",
    "author": "The Dhammapada",
    "source": "Verse 319, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-320",
    "text": "Silently shall I endure abuse as the elephant in battle endures the arrow sent from the bow: for the world is ill-natured.",
    "author": "The Dhammapada",
    "source": "Verse 320, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-321",
    "text": "They lead a tamed elephant to battle, the king mounts a tamed elephant; the tamed is the best among men, he who silently endures abuse.",
    "author": "The Dhammapada",
    "source": "Verse 321, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-322",
    "text": "Mules are good, if tamed, and noble Sindhu horses, and elephants with large tusks; but he who tames himself is better still.",
    "author": "The Dhammapada",
    "source": "Verse 322, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-323",
    "text": "For with these animals does no man reach the untrodden country (Nirvana), where a tamed man goes on a tamed animal, viz. on his own well-tamed self.",
    "author": "The Dhammapada",
    "source": "Verse 323, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-324",
    "text": "The elephant called Dhanapalaka, his temples running with sap, and difficult to hold, does not eat a morsel when bound; the elephant longs for the elephant grove.",
    "author": "The Dhammapada",
    "source": "Verse 324, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-326",
    "text": "This mind of mine went formerly wandering about as it liked, as it listed, as it pleased; but I shall now hold it in thoroughly, as the rider who holds the hook holds in the furious elephant.",
    "author": "The Dhammapada",
    "source": "Verse 326, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-328",
    "text": "If a man find a prudent companion who walks with him, is wise, and lives soberly, he may walk with him, overcoming all dangers, happy, but considerate.",
    "author": "The Dhammapada",
    "source": "Verse 328, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-329",
    "text": "If a man find no prudent companion who walks with him, is wise, and lives soberly, let him walk alone, like a king who has left his conquered country behind,--like an elephant in the forest.",
    "author": "The Dhammapada",
    "source": "Verse 329, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-333",
    "text": "Pleasant is virtue lasting to old age, pleasant is a faith firmly rooted; pleasant is attainment of intelligence, pleasant is avoiding of sins.",
    "author": "The Dhammapada",
    "source": "Verse 333, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-334",
    "text": "The thirst of a thoughtless man grows like a creeper; he runs from life to life, like a monkey seeking fruit in the forest.",
    "author": "The Dhammapada",
    "source": "Verse 334, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-335",
    "text": "Whomsoever this fierce thirst overcomes, full of poison, in this world, his sufferings increase like the abounding Birana grass.",
    "author": "The Dhammapada",
    "source": "Verse 335, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-336",
    "text": "He who overcomes this fierce thirst, difficult to be conquered in this world, sufferings fall off from him, like water-drops from a lotus leaf.",
    "author": "The Dhammapada",
    "source": "Verse 336, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-337",
    "text": "This salutary word I tell you, `Do ye, as many as are here assembled, dig up the root of thirst, as he who wants the sweet- scented Usira root must dig up the Birana grass, that Mara (the tempter) may not crush you again and again, as the stream crushes the reeds.'",
    "author": "The Dhammapada",
    "source": "Verse 337, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-338",
    "text": "As a tree, even though it has been cut down, is firm so long as its root is safe, and grows again, thus, unless the feeders of thirst are destroyed, the pain (of life) will return again and again.",
    "author": "The Dhammapada",
    "source": "Verse 338, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-339",
    "text": "He whose thirst running towards pleasure is exceeding strong in the thirty-six channels, the waves will carry away that misguided man, viz. his desires which are set on passion.",
    "author": "The Dhammapada",
    "source": "Verse 339, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-340",
    "text": "The channels run everywhere, the creeper (of passion) stands sprouting; if you see the creeper springing up, cut its root by means of knowledge.",
    "author": "The Dhammapada",
    "source": "Verse 340, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-341",
    "text": "A creature's pleasures are extravagant and luxurious; sunk in lust and looking for pleasure, men undergo (again and again) birth and decay.",
    "author": "The Dhammapada",
    "source": "Verse 341, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-342",
    "text": "Men, driven on by thirst, run about like a snared hare; held in fetters and bonds, they undergo pain for a long time, again and again.",
    "author": "The Dhammapada",
    "source": "Verse 342, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-343",
    "text": "Men, driven on by thirst, run about like a snared hare; let therefore the mendicant drive out thirst, by striving after passionlessness for himself.",
    "author": "The Dhammapada",
    "source": "Verse 343, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-346",
    "text": "That fetter wise people call strong which drags down, yields, but is difficult to undo; after having cut this at last, people leave the world, free from cares, and leaving desires and pleasures behind.",
    "author": "The Dhammapada",
    "source": "Verse 346, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-348",
    "text": "Give up what is before, give up what is behind, give up what is in the middle, when thou goest to the other shore of existence; if thy mind is altogether free, thou wilt not again enter into birth and decay.",
    "author": "The Dhammapada",
    "source": "Verse 348, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-349",
    "text": "If a man is tossed about by doubts, full of strong passions, and yearning only for what is delightful, his thirst will grow more and more, and he will indeed make his fetters strong.",
    "author": "The Dhammapada",
    "source": "Verse 349, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-352",
    "text": "He who is without thirst and without affection, who understands the words and their interpretation, who knows the order of letters (those which are before and which are after), he has received his last body, he is called the great sage, the great man.",
    "author": "The Dhammapada",
    "source": "Verse 352, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-353",
    "text": "`I have conquered all, I know all, in all conditions of life I am free from taint; I have left all, and through the destruction of thirst I am free; having learnt myself, whom shall I teach?'",
    "author": "The Dhammapada",
    "source": "Verse 353, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-354",
    "text": "The gift of the law exceeds all gifts; the sweetness of the law exceeds all sweetness; the delight in the law exceeds all delights; the extinction of thirst overcomes all pain.",
    "author": "The Dhammapada",
    "source": "Verse 354, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-355",
    "text": "Pleasures destroy the foolish, if they look not for the other shore; the foolish by his thirst for pleasures destroys himself, as if he were his own enemy.",
    "author": "The Dhammapada",
    "source": "Verse 355, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-356",
    "text": "The fields are damaged by weeds, mankind is damaged by passion: therefore a gift bestowed on the passionless brings great reward.",
    "author": "The Dhammapada",
    "source": "Verse 356, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-357",
    "text": "The fields are damaged by weeds, mankind is damaged by hatred: therefore a gift bestowed on those who do not hate brings great reward.",
    "author": "The Dhammapada",
    "source": "Verse 357, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-358",
    "text": "The fields are damaged by weeds, mankind is damaged by vanity: therefore a gift bestowed on those who are free from vanity brings great reward.",
    "author": "The Dhammapada",
    "source": "Verse 358, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-359",
    "text": "The fields are damaged by weeds, mankind is damaged by lust: therefore a gift bestowed on those who are free from lust brings great reward.",
    "author": "The Dhammapada",
    "source": "Verse 359, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-360",
    "text": "Restraint in the eye is good, good is restraint in the ear, in the nose restraint is good, good is restraint in the tongue.",
    "author": "The Dhammapada",
    "source": "Verse 360, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-361",
    "text": "In the body restraint is good, good is restraint in speech, in thought restraint is good, good is restraint in all things. A Bhikshu, restrained in all things, is freed from all pain.",
    "author": "The Dhammapada",
    "source": "Verse 361, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-362",
    "text": "He who controls his hand, he who controls his feet, he who controls his speech, he who is well controlled, he who delights inwardly, who is collected, who is solitary and content, him they call Bhikshu.",
    "author": "The Dhammapada",
    "source": "Verse 362, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-363",
    "text": "The Bhikshu who controls his mouth, who speaks wisely and calmly, who teaches the meaning and the law, his word is sweet.",
    "author": "The Dhammapada",
    "source": "Verse 363, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-364",
    "text": "He who dwells in the law, delights in the law, meditates on the law, follows the law, that Bhikshu will never fall away from the true law.",
    "author": "The Dhammapada",
    "source": "Verse 364, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-367",
    "text": "He who never identifies himself with name and form, and does not grieve over what is no more, he indeed is called a Bhikshu.",
    "author": "The Dhammapada",
    "source": "Verse 367, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-369",
    "text": "O Bhikshu, empty this boat! if emptied, it will go quickly; having cut off passion and hatred thou wilt go to Nirvana.",
    "author": "The Dhammapada",
    "source": "Verse 369, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-370",
    "text": "Cut off the five (senses), leave the five, rise above the five. A Bhikshu, who has escaped from the five fetters, he is called Oghatinna, `saved from the flood.'",
    "author": "The Dhammapada",
    "source": "Verse 370, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-372",
    "text": "Without knowledge there is no meditation, without meditation there is no knowledge: he who has knowledge and meditation is near unto Nirvana.",
    "author": "The Dhammapada",
    "source": "Verse 372, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-373",
    "text": "A Bhikshu who has entered his empty house, and whose mind is tranquil, feels a more than human delight when he sees the law clearly.",
    "author": "The Dhammapada",
    "source": "Verse 373, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-374",
    "text": "As soon as he has considered the origin and destruction of the elements (khandha) of the body, he finds happiness and joy which belong to those who know the immortal (Nirvana).",
    "author": "The Dhammapada",
    "source": "Verse 374, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-375",
    "text": "And this is the beginning here for a wise Bhikshu: watchfulness over the senses, contentedness, restraint under the law; keep noble friends whose life is pure, and who are not slothful.",
    "author": "The Dhammapada",
    "source": "Verse 375, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-376",
    "text": "Let him live in charity, let him be perfect in his duties; then in the fulness of delight he will make an end of suffering.",
    "author": "The Dhammapada",
    "source": "Verse 376, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-377",
    "text": "As the Vassika plant sheds its withered flowers, men should shed passion and hatred, O ye Bhikshus!",
    "author": "The Dhammapada",
    "source": "Verse 377, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-378",
    "text": "The Bhikshu whose body and tongue and mind are quieted, who is collected, and has rejected the baits of the world, he is called quiet.",
    "author": "The Dhammapada",
    "source": "Verse 378, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-379",
    "text": "Rouse thyself by thyself, examine thyself by thyself, thus self- protected and attentive wilt thou live happily, O Bhikshu!",
    "author": "The Dhammapada",
    "source": "Verse 379, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "dhammapada-380",
    "text": "For self is the lord of self, self is the refuge of self; therefore curb thyself as the merchant curbs a good horse.",
    "author": "The Dhammapada",
    "source": "Verse 380, translated by F. Max Müller",
    "url": "https://en.wikisource.org/wiki/Dhammapada_(Muller)",
    "topics": [
      "Religion",
      "Life"
    ]
  },
  {
    "id": "prophet-line-253",
    "text": "People of Orphalese, of what can I speak save of that which is even now moving within your souls?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-274",
    "text": "For even as love crowns you so shall he crucify you. Even as he is for your growth so is he for your pruning.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-291",
    "text": "And then he assigns you to his sacred fire, that you may become sacred bread for God's sacred feast.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-295",
    "text": "All these things shall love do unto you that you may know the secrets of your heart, and in that knowledge become a fragment of Life's heart.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-308",
    "text": "Love gives naught but itself and takes naught but from itself.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-318",
    "text": "And think not you can direct the course of love, for love, if it finds you worthy, directs your course.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-323",
    "text": "To melt and be like a running brook that sings its melody to the night.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-336",
    "text": "And then to sleep with a prayer for the beloved in your heart and a song of praise upon your lips.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-342",
    "text": "You were born together, and together you shall be forevermore.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-346",
    "text": "Aye, you shall be together even in the silent memory of God.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-350",
    "text": "And let the winds of the heavens dance between you.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-353",
    "text": "Let it rather be a moving sea between the shores of your souls.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-357",
    "text": "Give one another of your bread but eat not from the same loaf.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-361",
    "text": "Even as the strings of a lute are alone though they quiver with the same music.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-365",
    "text": "Give your hearts, but not into each other's keeping.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-367",
    "text": "For only the hand of Life can contain your hearts.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-384",
    "text": "And though they are with you yet they belong not to you.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-393",
    "text": "For their souls dwell in the house of tomorrow, which you cannot visit, not even in your dreams.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-395",
    "text": "You may strive to be like them, but seek not to make them like you. For life goes not backward nor tarries with yesterday.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-397",
    "text": "You are the bows from which your children as living arrows are sent forth.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-399",
    "text": "The archer sees the mark upon the path of the infinite, and He bends you with His might that His arrows may go swift and far.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-402",
    "text": "For even as he loves the arrow that flies, so He loves also the bow that is stable.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-408",
    "text": "You give but little when you give of your possessions.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-412",
    "text": "For what are your possessions but things you keep and guard for fear you may need them tomorrow?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-413",
    "text": "And tomorrow, what shall tomorrow bring to the overprudent dog burying bones in the trackless sand as he follows the pilgrims to the holy city?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-417",
    "text": "Is not dread of thirst when your well is full, thirst that is unquenchable?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-421",
    "text": "There are those who give little of the much which they have—and they give it for recognition and their hidden desire makes their gifts unwholesome.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-423",
    "text": "And there are those who have little and give it all.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-426",
    "text": "There are those who give with joy, and that joy is their reward.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-428",
    "text": "And there are those who give with pain, and that pain is their baptism.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-433",
    "text": "Through the hands of such as these God speaks, and from behind their eyes He smiles upon the earth.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-447",
    "text": "Therefore give now, that the season of giving may be yours and not your inheritors'.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-450",
    "text": "The trees in your orchard say not so, nor the flocks in your pasture.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-454",
    "text": "Surely he who is worthy to receive his days and his nights, is worthy of all else from you.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-457",
    "text": "And what desert greater shall there be, than that which lies in the courage and the confidence, nay the charity, of receiving?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-459",
    "text": "And who are you that men should rend their bosom and unveil their pride, that you may see their worth naked and their pride unabashed?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-461",
    "text": "See first that you yourself deserve to be a giver, and an instrument of giving.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-463",
    "text": "For in truth it is life that gives unto life—while you, who deem yourself a giver, are but a witness.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-468",
    "text": "For to be overmindful of your debt, is to doubt his generosity who has the freehearted earth for mother, and God for father.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-473",
    "text": "Would that you could live on the fragrance of the earth, and like an air plant be sustained by the light.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-477",
    "text": "And let your board stand an altar on which the pure and the innocent of forest and plain are sacrificed for that which is purer and still more innocent in man.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-484",
    "text": "For the law that delivered you into my hand shall deliver me into a mightier hand.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-509",
    "text": "And let there be in the song a remembrance for the autumn days, and for the vineyard, and for the winepress.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-514",
    "text": "You work that you may keep pace with the earth and the soul of the earth.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-516",
    "text": "For to be idle is to become a stranger unto the seasons, and to step out of life's procession, that marches in majesty and proud submission towards the infinite.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-520",
    "text": "When you work you are a flute through whose heart the whispering of the hours turns to music.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-522",
    "text": "Which of you would be a reed, dumb and silent, when all else sings together in unison?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-526",
    "text": "Always you have been told that work is a curse and labour a misfortune.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-531",
    "text": "And to love life through labour is to be intimate with life's inmost secret.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-536",
    "text": "You have been told also life is darkness, and in your weariness you echo what was said by the weary.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-571",
    "text": "And if you cannot work with love but only with distaste, it is better that you should leave your work and sit at the gate of the temple and take alms of those who work with joy.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-573",
    "text": "For if you bake bread with indifference, you bake a bitter bread that feeds but half man's hunger.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-575",
    "text": "And if you grudge the crushing of the grapes, your grudge distils a poison in the wine.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-576",
    "text": "And if you sing though as angels, and love not the singing, you muffle man's ears to the voices of the day and the voices of the night.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-588",
    "text": "The deeper that sorrow carves into your being, the more joy you can contain.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-589",
    "text": "Is not the cup that holds your wine the very cup that was burned in the potter's oven?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-591",
    "text": "And is not the lute that soothes your spirit, the very wood that was hollowed with knives?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-593",
    "text": "When you are joyous, look deep into your heart and you shall find it is only that which has given you sorrow that is giving you joy.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-595",
    "text": "When you are sorrowful look again in your heart, and you shall see that in truth you are weeping for that which has been your delight.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-600",
    "text": "Together they come, and when one sits alone with you at your board, remember that the other is asleep upon your bed.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-604",
    "text": "Verily you are suspended like scales between your sorrow and your joy.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-606",
    "text": "Only when you are empty are you at standstill and balanced.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-608",
    "text": "When the treasure-keeper lifts you to weigh his gold and his silver, needs must your joy or your sorrow rise or fall.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-613",
    "text": "Build of your imaginings a bower in the wilderness ere you build a house within the city walls.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-615",
    "text": "For even as you have home-comings in your twilight, so has the wanderer in you, the ever distant and alone.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-620",
    "text": "Would that I could gather your houses into my hand, and like a sower scatter them in forest and meadow.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-622",
    "text": "Would the valleys were your streets, and the green paths your alleys, that you might seek one another through vineyards, and come with the fragrance of the earth in your garments.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-626",
    "text": "In their fear your forefathers gathered you too near together. And that fear shall endure a little longer. A little longer shall your city walls separate your hearths from your fields.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-629",
    "text": "And tell me, people of Orphalese, what have you in these houses? And what is it you guard with fastened doors?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-631",
    "text": "Have you peace, the quiet urge that reveals your power?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-633",
    "text": "Have you remembrances, the glimmering arches that span the summits of the mind?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-635",
    "text": "Have you beauty, that leads the heart from things fashioned of wood and stone to the holy mountain?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-642",
    "text": "Ay, and it becomes a tamer, and with hook and scourge makes puppets of your larger desires.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-649",
    "text": "Verily the lust for comfort murders the passion of the soul, and then walks grinning in the funeral.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-658",
    "text": "You shall not fold your wings that you may pass through doors, nor bend your heads that they strike not against a ceiling, nor fear to breathe lest walls should crack and fall down.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-662",
    "text": "And though of magnificence and splendour, your house shall not hold your secret nor shelter your longing.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-663",
    "text": "For that which is boundless in you abides in the mansion of the sky, whose door is the morning mist, and whose windows are the songs and the silences of night.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-669",
    "text": "Your clothes conceal much of your beauty, yet they hide not the unbeautiful.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-671",
    "text": "And though you seek in garments the freedom of privacy you may find in them a harness and a chain.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-674",
    "text": "For the breath of life is in the sunlight and the hand of life is in the wind.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-686",
    "text": "Forget not that modesty is for a shield against the eye of the unclean.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-689",
    "text": "And forget not that the earth delights to feel your bare feet and the winds long to play with your hair.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-695",
    "text": "To you the earth yields her fruit, and you shall not want if you but know how to fill your hands.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-702",
    "text": "Invoke then the master spirit of the earth, to come into your midst and sanctify the scales and the reckoning that weighs value against value.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-704",
    "text": "And suffer not the barren-handed to take part in your transactions, who would sell their words for your labour.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-713",
    "text": "And if there come the singers and the dancers and the flute players,—buy of their gifts also.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-715",
    "text": "For they too are gatherers of fruit and frankincense, and that which they bring, though fashioned of dreams, is raiment and food for your soul.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-719",
    "text": "And before you leave the market place, see that no one has gone his way with empty hands.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-720",
    "text": "For the master spirit of the earth shall not sleep peacefully upon the wind till the needs of the least of you are satisfied.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-730",
    "text": "And for that wrong committed must you knock and wait a while unheeded at the gate of the blessed.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-748",
    "text": "For it is he and not your god-self nor the pigmy in the mist, that knows crime and the punishment of crime.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-752",
    "text": "Oftentimes have I heard you speak of one who commits a wrong as though he were not one of you, but a stranger unto you and an intruder upon your world.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-761",
    "text": "Like a procession you walk together towards your god-self.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-767",
    "text": "Ay, and he falls for those ahead of him, who though faster and surer of foot, yet removed not the stumbling stone.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-783",
    "text": "For they stand together before the face of the sun even as the black thread and the white are woven together.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-793",
    "text": "And let him who would lash the offender look unto the spirit of the offended.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-796",
    "text": "And verily he will find the roots of the good and the bad, the fruitful and the fruitless, all entwined together in the silent heart of the earth.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-811",
    "text": "Is not remorse the justice which is administered by that very law which you would fain serve?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-815",
    "text": "Unbidden shall it call in the night, that men may wake and gaze upon themselves.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-820",
    "text": "And that the corner-stone of the temple is not higher than the lowest stone in its foundation.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-829",
    "text": "Like children playing by the ocean who build sand-towers with constancy and then destroy them with laughter.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-844",
    "text": "What of the ox who loves his yoke and deems the elk and deer of the forest stray and vagrant things?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-846",
    "text": "What of the old serpent who cannot shed his skin, and calls all others naked and shameless?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-848",
    "text": "And of him who comes early to the wedding-feast, and when over-fed and tired goes his way saying that all feasts are violation and all feasters law-breakers?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-852",
    "text": "What shall I say of these save that they too stand in the sunlight, but with their backs to the sun?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-855",
    "text": "And what is the sun to them but a caster of shadows?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-857",
    "text": "And what is it to acknowledge the laws but to stoop down and trace their shadows upon the earth?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-861",
    "text": "You who travel with the wind, what weather-vane shall direct your course?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-863",
    "text": "What man's law shall bind you if you break your yoke but upon no man's prison door?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-864",
    "text": "What laws shall you fear if you dance but stumble against no man's iron chains?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-866",
    "text": "And who is he that shall bring you to judgment if you tear off your garment yet leave it in no man's path?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-870",
    "text": "People of Orphalese, you can muffle the drum, and you can loosen the strings of the lyre, but who shall command the skylark not to sing?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-879",
    "text": "Ay, in the grove of the temple and in the shadow of the citadel I have seen the freest among you wear their freedom as a yoke and a handcuff.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-881",
    "text": "And my heart bled within me; for you can only be free when even the desire of seeking freedom becomes a harness to you, and when you cease to speak of freedom as a goal and a fulfilment.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-888",
    "text": "And how shall you rise beyond your days and nights unless you break the chains which you at the dawn of your understanding have fastened around your noon hour?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-890",
    "text": "In truth that which you call freedom is the strongest of these chains, though its links glitter in the sun and dazzle the eyes.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-891",
    "text": "And what is it but fragments of your own self you would discard that you may become free?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-895",
    "text": "You cannot erase it by burning your law books nor by washing the foreheads of your judges, though you pour the sea upon them.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-897",
    "text": "And if it is a despot you would dethrone, see first that his throne erected within you is destroyed.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-898",
    "text": "For how can a tyrant rule the free and the proud, but for a tyranny in their own freedom and a shame in their own pride?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-900",
    "text": "And if it is a care you would cast off, that care has been chosen by you rather than imposed upon you.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-902",
    "text": "And if it is a fear you would dispel, the seat of that fear is in your heart and not in the hand of the feared.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-903",
    "text": "Verily all things move within your being in constant half embrace, the desired and the dreaded, the repugnant and the cherished, the pursued and that which you would escape.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-909",
    "text": "And thus your freedom when it loses its fetters becomes itself the fetter of a greater freedom.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-914",
    "text": "Your soul is oftentimes a battlefield, upon which your reason and your judgment wage war against your passion and your appetite.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-916",
    "text": "Would that I could be the peacemaker in your soul, that I might turn the discord and the rivalry of your elements into oneness and melody.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-919",
    "text": "Your reason and your passion are the rudder and the sails of your seafaring soul.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-923",
    "text": "For reason, ruling alone, is a force confining; and passion, unattended, is a flame that burns to its own destruction.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-926",
    "text": "And let it direct your passion with reason, that your passion may live through its own daily resurrection, and like the phoenix rise above its own ashes.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-930",
    "text": "I would have you consider your judgment and your appetite even as you would two loved guests in your house.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-932",
    "text": "Surely you would not honour one guest above the other; for he who is more mindful of one loses the love and the faith of both.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-937",
    "text": "And since you are a breath in God's sphere, and a leaf in God's forest, you too should rest in reason and move in passion.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-942",
    "text": "Your pain is the breaking of the shell that encloses your understanding.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-944",
    "text": "Even as the stone of the fruit must break, that its heart may stand in the sun, so must you know pain.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-968",
    "text": "Your hearts know in silence the secrets of the days and the nights.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-972",
    "text": "You would know in words that which you have always known in thought.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-974",
    "text": "You would touch with your fingers the naked body of your dreams.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-983",
    "text": "And seek not the depths of your knowledge with staff or sounding line.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-992",
    "text": "The soul walks not upon a line, neither does it grow like a reed.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-994",
    "text": "The soul unfolds itself, like a lotus of countless petals. Then said a teacher, Speak to us of Teaching.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-998",
    "text": "No man can reveal to you aught but that which already lies half asleep in the dawning of your knowledge.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1000",
    "text": "The teacher who walks in the shadow of the temple, among his followers, gives not of his wisdom but rather of his faith and his lovingness.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1003",
    "text": "The astronomer may speak to you of his understanding of space, but he cannot give you his understanding.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1005",
    "text": "The musician may sing to you of the rhythm which is in all space, but he cannot give you the ear which arrests the rhythm nor the voice that echoes it.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1008",
    "text": "For the vision of one man lends not its wings to another man.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1010",
    "text": "And even as each one of you stands alone in God's knowledge, so must each one of you be alone in his knowledge of God and in his understanding of the earth.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1021",
    "text": "For you come to him with your hunger, and you seek him for peace.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1029",
    "text": "For without words, in friendship, all thoughts, all desires, all expectations are born and shared, with joy that is unacclaimed.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1032",
    "text": "For that which you love most in him may be clearer in his absence, as the mountain to the climber is clearer from the plain.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1034",
    "text": "And let there be no purpose in friendship save the deepening of the spirit.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1036",
    "text": "For love that seeks aught but the disclosure of its own mystery is not love but a net cast forth: and only the unprofitable is caught.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1047",
    "text": "For it is his to fill your need, but not your emptiness.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1049",
    "text": "And in the sweetness of friendship let there be laughter, and sharing of pleasures.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1051",
    "text": "For in the dew of little things the heart finds its morning and is refreshed.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1060",
    "text": "And in much of your talking, thinking is half murdered.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1062",
    "text": "For thought is a bird of space, that in a cage of words many indeed unfold its wings but cannot fly.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1066",
    "text": "There are those among you who seek the talkative through fear of being alone.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1068",
    "text": "The silence of aloneness reveals to their eyes their naked selves and they would escape.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1069",
    "text": "And there are those who talk, and without knowledge or forethought reveal a truth which they themselves do not understand.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1071",
    "text": "And there are those who have the truth within them, but they tell it not in words.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1073",
    "text": "In the bosom of such as these the spirit dwells in rhythmic silence.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1077",
    "text": "When you meet your friend on the roadside or in the market place, let the spirit in you move your lips and direct your tongue.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1082",
    "text": "When the colour is forgotten and the vessel is no more.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1088",
    "text": "You would measure time the measureless and the immeasurable.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1090",
    "text": "You would adjust your conduct and even direct the course of your spirit according to hours and seasons.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1092",
    "text": "Of time you would make a stream upon whose bank you would sit and watch its flowing.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1095",
    "text": "And knows that yesterday is but today's memory and tomorrow is today's dream.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1097",
    "text": "And that that which sings and contemplates in you is still dwelling within the bounds of that first moment which scattered the stars into space.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1099",
    "text": "Who among you does not feel that his power to love is boundless?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1100",
    "text": "And yet who does not feel that very love, though boundless, encompassed within the centre of his being, and moving not from love thought to love thought, nor from love deeds to other love deeds?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1102",
    "text": "And is not time even as love is, undivided and paceless?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1108",
    "text": "And let today embrace the past with remembrance and the future with longing.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1125",
    "text": "For a divided house is not a den of thieves; it is only a divided house.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1132",
    "text": "For when you strive for gain you are but a root that clings to the earth and sucks at her breast.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1136",
    "text": "For to the fruit giving is a need, as receiving is a need to the root.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1141",
    "text": "And even stumbling speech may strengthen a weak tongue.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1145",
    "text": "You are good when you walk to your goal firmly and with bold steps.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1156",
    "text": "Pity that the stags cannot teach swiftness to the turtles.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1160",
    "text": "In your longing for your giant self lies your goodness: and that longing is in all of you.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1163",
    "text": "And in others it is a flat stream that loses itself in angles and bends and lingers before it reaches the shore.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1172",
    "text": "You pray in your distress and in your need; would that you might pray also in the fullness of your joy and in your days of abundance.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1176",
    "text": "For what is prayer but the expansion of yourself into the living ether?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1178",
    "text": "And if it is for your comfort to pour your darkness into space, it is also for your delight to pour forth the dawning of your heart.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1180",
    "text": "And if you cannot but weep when your soul summons you to prayer, she should spur you again and yet again, though weeping, until you shall come laughing.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1185",
    "text": "Therefore let your visit to that temple invisible be for naught but ecstasy and sweet communion.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1198",
    "text": "God listens not to your words save when He Himself utters them through your lips.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1237",
    "text": "Some of your youth seek pleasure as if it were all, and they are judged and rebuked.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1239",
    "text": "I would not judge nor rebuke them. I would have them seek.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1243",
    "text": "Seven are her sisters, and the least of them is more beautiful than pleasure.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1245",
    "text": "Have you not heard of the man who was digging in the earth for roots and found a treasure?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1249",
    "text": "And some of your elders remember pleasures with regret like wrongs committed in drunkenness.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1260",
    "text": "And in their fear of seeking and remembering they shun all pleasures, lest they neglect the spirit or offend against it.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1263",
    "text": "And thus they too find a treasure though they dig for roots with quivering hands.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1267",
    "text": "Shall the nightingale offend the stillness of the night, or the firefly the stars?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1269",
    "text": "And shall your flame or your smoke burden the wind?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1271",
    "text": "Think you the spirit is a still pool which you can trouble with a staff?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1275",
    "text": "Oftentimes in denying yourself pleasure you do but store the desire in the recesses of your being.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1276",
    "text": "Who knows but that which seems omitted today, waits for tomorrow?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1278",
    "text": "Even your body knows its heritage and its rightful need and will not be deceived.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1282",
    "text": "And it is yours to bring forth sweet music from it or confused sounds.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1295",
    "text": "And to both, bee and flower, the giving and the receiving of pleasure is a need and an ecstasy.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1299",
    "text": "People of Orphalese, be in your pleasures like the flowers and the bees.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1305",
    "text": "Where shall you seek beauty, and how shall you find her unless she herself be your way and your guide?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1306",
    "text": "And how shall you speak of her except she be the weaver of your speech?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1355",
    "text": "People of Orphalese, beauty is life when life unveils her holy face.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1370",
    "text": "And that which is neither deed nor reflection, but a wonder and a surprise ever springing in the soul, even while the hands hew the stone or tend the loom?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1372",
    "text": "Who can separate his faith from his actions, or his belief from his occupations?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1375",
    "text": "All your hours are wings that beat through space from self to self.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1379",
    "text": "The wind and the sun will tear no holes in his skin.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1390",
    "text": "Whenever you enter into it take with you your all.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1394",
    "text": "The things you have fashioned in necessity or for delight.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1396",
    "text": "For in revery you cannot rise above your achievements nor fall lower than your failures.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1399",
    "text": "For in adoration you cannot fly higher than their hopes nor humble yourself lower than their despair.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1403",
    "text": "And if you would know God be not therefore a solver of riddles.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1405",
    "text": "Rather look about you and you shall see Him playing with your children.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1407",
    "text": "And look into space; you shall see Him walking in the cloud, outstretching His arms in the lightning and descending in rain.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1409",
    "text": "You shall see Him smiling in flowers, then rising and waving His hands in trees.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1418",
    "text": "The owl whose night-bound eyes are blind unto the day cannot unveil the mystery of light.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1427",
    "text": "And like seeds dreaming beneath the snow your heart dreams of spring.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1429",
    "text": "Trust the dreams, for in them is hidden the gate to eternity.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1435",
    "text": "Is the shepherd not joyful beneath his trembling, that he shall wear the mark of the king?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1442",
    "text": "And what is it to cease breathing, but to free the breath from its restless tides, that it may rise and expand and seek God unencumbered?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1446",
    "text": "Only when you drink from the river of silence shall you indeed sing.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1467",
    "text": "We wanderers, ever seeking the lonelier way, begin no day where we have ended another day; and no sunrise finds us where sunset left us.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1470",
    "text": "We are the seeds of the tenacious plant, and it is in our ripeness and our fullness of heart that we are given to the wind and are scattered.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1474",
    "text": "Brief were my days among you, and briefer still the words I have spoken.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1478",
    "text": "And with a richer heart and lips more yielding to the spirit will I speak.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1491",
    "text": "And if this day is not a fulfilment of your needs and my love, then let it be a promise till another day.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1492",
    "text": "Man's needs change, but not his love, nor his desire that his love should satisfy his needs.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1494",
    "text": "Know therefore, that from the greater silence I shall return.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1496",
    "text": "The mist that drifts away at dawn, leaving but dew in the fields, shall rise and gather into a cloud and then fall down in rain.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1501",
    "text": "And your heart-beats were in my heart, and your breath was upon my face, and I knew you all.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1503",
    "text": "Ay, I knew your joy and your pain, and in your sleep your dreams were my dreams.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1505",
    "text": "And oftentimes I was among you a lake among the mountains.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1509",
    "text": "bending slopes, and even the passing flocks of your thoughts and your desires.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1511",
    "text": "And to my silence came the laughter of your children in streams, and the longing of your youths in rivers.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1526",
    "text": "And in beholding him that I beheld you and loved you.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1528",
    "text": "For what distances can love reach that are not in that vast sphere?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1529",
    "text": "What visions, what expectations and what presumptions can outsoar that flight?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1531",
    "text": "Like a giant oak tree covered with apple blossoms is the vast man in you.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1537",
    "text": "You have been told that, even like a chain, you are as weak as your weakest link.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1539",
    "text": "This is but half the truth. You are also as strong as your strongest link.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1540",
    "text": "To measure you by your smallest deed is to reckon the power of ocean by the frailty of its foam.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1542",
    "text": "To judge you by your failures is to cast blame upon the seasons for their inconsistency.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1548",
    "text": "And though heavy-grounded ships await the tide upon your shores, yet, even like an ocean, you cannot hasten your tides.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1557",
    "text": "I only speak to you in words of that which you yourselves know in thought.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1559",
    "text": "And what is word knowledge but a shadow of wordless knowledge?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1565",
    "text": "And of nights when earth was upwrought with confusion.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1568",
    "text": "And behold I have found that which is greater than wisdom.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1572",
    "text": "While you, heedless of its expansion, bewail the withering of your days.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1581",
    "text": "Whenever you pass by the field where you have laid your ancestors look well thereupon, and you shall see yourselves and your children dancing hand in hand.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1587",
    "text": "Others have come to you to whom for golden promises made unto your faith you have given but riches and power and glory.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1589",
    "text": "Less than a promise have I given, and yet more generous have you been to me.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1592",
    "text": "Surely there is no greater gift to a man than that which turns all his aims into parching lips and all life into a fountain.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1602",
    "text": "Some of you have deemed me proud and over-shy to receive gifts.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1604",
    "text": "Too proud indeed am I to receive wages, but not gifts.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1626",
    "text": "True it is that I have climbed the hills and walked in remote places.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1628",
    "text": "How could I have seen you save from a great height or a great distance?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1656",
    "text": "For many of my arrows left my bow only to seek my own breast.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1660",
    "text": "For when my wings were spread in the sun their shadow upon the earth was a turtle.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1663",
    "text": "For often have I put my finger in my own wound that I might have the greater belief in you and the greater knowledge of you.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1682",
    "text": "Life, and all that lives, is conceived in the mist and not in the crystal.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1691",
    "text": "Is it not your breath that has erected and hardened the structure of your bones?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1693",
    "text": "And is it not a dream which none of you remember having dreamt, that builded your city and fashioned all there is in it?",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1697",
    "text": "And if you could hear the whispering of the dream you would hear no other sound.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1718",
    "text": "After saying these things he looked about him, and he saw the pilot of his ship standing by the helm and gazing now at the full sails and now at the distance.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1729",
    "text": "And these my mariners, who have heard the choir of the greater sea, they too have heard me patiently.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1735",
    "text": "The stream has reached the sea, and once more the great mother holds her son against her breast.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1746",
    "text": "And if it suffices not, then again must we come together and together stretch our hands unto the giver.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "prophet-line-1750",
    "text": "A little while, and my longing shall gather dust and foam for another body.",
    "author": "Kahlil Gibran",
    "source": "The Prophet (1923)",
    "url": "https://en.wikisource.org/wiki/The_Prophet_(Gibran)",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "meditations-II-109-2971324094",
    "text": "From thence all things flow; and there is besides necessity, and that which is for the advantage of the whole universe, of which thou art a part.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book II, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_II",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-II-115-2710723510",
    "text": "Give thyself time to learn something new and good, and cease to be whirled around.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book II, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_II",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-II-116-393155949",
    "text": "Through not observing what is in the mind of another a man has seldom been seen to be unhappy; but those who do not observe the movements of their own minds must of necessity be unhappy.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book II, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_II",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-II-124-1854601462",
    "text": "Now that which does not make a man worse, how can it make a man's life worse?",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book II, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_II",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-II-135-2773735819",
    "text": "The soul of man does violence to itself, first of all, when it becomes an abscess, and, as it were, a tumor on the universe, so far as it can.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book II, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_II",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-II-135-3833359859",
    "text": "In the next place, the soul does violence to itself when it turns away from any man, or even moves towards him with the intention of injuring, such as are the souls of those who are angry.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book II, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_II",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-II-136-2818018963",
    "text": "In the third place, the soul does violence to itself when it is overpowered by pleasure or by pain.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book II, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_II",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-III-107-3732029312",
    "text": "We ought to observe also that even the things which follow after the things which are produced according to nature contain something pleasing and attractive.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book III, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_III",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-III-113-2621372759",
    "text": "Do not waste the remainder of thy life in thoughts about others, when thou dost not refer thy thoughts to some object of common utility.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book III, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_III",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-III-118-102669246",
    "text": "Accordingly, he does not value at all the praise which comes from such men, since they are not even satisfied with themselves.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book III, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_III",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-III-120-951232837",
    "text": "A man then must stand erect, not be kept erect by others.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book III, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_III",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-III-127-4218243596",
    "text": "On this faculty it entirely depends whether there shall exist in thy ruling part any opinion inconsistent with nature and the constitution of the rational animal.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book III, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_III",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-III-138-2489250243",
    "text": "Body, soul, intelligence: to the body belong sensation, to the soul appetites, to the intelligence principles.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book III, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_III",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-106-2997863618",
    "text": "Let no act be done without a purpose, nor otherwise than according to the perfect principles of art.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-107-3748100842",
    "text": "Men seek retreats for themselves, houses in the country, sea-shores, and mountains; and thou too art wont to desire such things very much.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-113-1356839736",
    "text": "The other is that all these things, which thou seest, change immediately and will no longer be; and constantly bear in mind how many of these changes thou hast already witnessed.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-123-1902212596",
    "text": "Observe then as thou hast begun; and whatever thou doest, do it in conjunction with this, the being good, and in the sense in which a man is properly understood to be good.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-124-1491245983",
    "text": "Do not have such an opinion of things as he has who does thee wrong, or such as he wishes thee to have, but look at them as they are in truth.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-131-4213858586",
    "text": "Within ten days thou wilt seem a god to those to whom thou art now a beast and an ape, if thou wilt return to thy principles and the worship of reason.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-133-3991104403",
    "text": "Do not act as if thou wert going to live ten thousand years.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-137-2897533806",
    "text": "Everything which is in any way beautiful is beautiful in itself, and terminates in itself, not having praise as part of itself.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-137-3966230296",
    "text": "I affirm this also of the things which are called beautiful by the vulgar, for example, material things and works of art.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-146-2078038938",
    "text": "Nothing for me is too early nor too late, which is in due time for thee.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-146-273122838",
    "text": "Everything is fruit to me which thy seasons bring, O Nature: from thee are all things, in thee are all things, to thee all things return.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-147-2613289973",
    "text": "—But consider if it would not be better to say, Do what is necessary, and whatever the reason of the animal which is naturally social requires, and as it requires.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-148-947191985",
    "text": "Accordingly, on every occasion a man should ask himself, Is this one of the unnecessary things?",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-148-3283614058",
    "text": "Now a man should take away not only unnecessary acts, but also unnecessary thoughts, for thus superfluous acts will not follow after.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-149-4095801861",
    "text": "Try how the life of the good man suits thee, the life of him who is satisfied with his portion out of the whole, and satisfied with his own just acts and benevolent disposition.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-159-3330048663",
    "text": "Well, then, that life of these people no longer exists at all.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-160-2877197336",
    "text": "In like manner view also the other epochs of time and of whole nations, and see how many after great efforts soon fell and were resolved into the elements.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-170-2011923192",
    "text": "Examine men's ruling principles, even those of the wise, what kind of things they avoid, and what kind they pursue.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-178-3256224255",
    "text": "Time is like a river made up of the events which happen, and a violent stream; for as soon as a thing has been seen, it is carried away, and another comes in its place, and this will be carried away too.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-187-3661238499",
    "text": "Pass then through this little space of time conformably to nature, and end thy journey in content, as an olive falls off when it is ripe, blessing nature who produced it, and thanking the tree on which it grew.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-190-1283795722",
    "text": "Why then is that rather a misfortune than this a good fortune?",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-191-3604150756",
    "text": "Remember too on every occasion which leads thee to vexation to apply this principle; not that this is a misfortune, but that to bear it nobly is good fortune.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IV-194-3341304845",
    "text": "Always run to the short way; and the short way is the natural: accordingly say and do everything in conformity with the soundest reason.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IV, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IV",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-104-3317114046",
    "text": "I N the morning when thou risest unwillingly, let this thought be present,—I am rising to the work of a human being.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-105-3262276462",
    "text": "Why then am I dissatisfied if I am going to do the things for which I exist and for which I was brought into the world?",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-112-2693090921",
    "text": "—Be it so: but there are many other things of which thou canst not say, I am not formed from them by nature.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-113-2363093936",
    "text": "Dost thou not see how many qualities thou art immediately able to exhibit, in which there is no excuse of natural incapacity and unfitness, and yet thou still remainest voluntarily below the mark?",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-114-2582785234",
    "text": "Only if in truth thou canst be charged with being rather slow and dull of comprehension, thou must exert thyself about this also, not neglecting it nor yet taking pleasure in thy dullness.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-115-4169432088",
    "text": "Another is not ready to do this, but still in his own mind he thinks of the man as his debtor, and he knows what he has done.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-116-59968902",
    "text": "—Must a man then be one of these, who in a manner act thus without observing it?",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-118-2527325604",
    "text": "—In truth we ought not to pray at all, or we ought to pray in this simple and noble fashion.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-123-1644162779",
    "text": "Neither does the nature of anything, whatever it may be, cause anything which is not suitable to that which is directed by it.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-130-347343972",
    "text": "Then turn to the morals of those who live with thee, and it is hardly possible to endure even the most agreeable of them, to say nothing of a man being hardly able to endure himself.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-137-3709528000",
    "text": "Every part of me then will be reduced by change into some part of the universe, and that again will change into another part of the universe, and so on forever.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-140-654091478",
    "text": "None of these things ought to be called a man's, which do not belong to a man, as man.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-140-2541273469",
    "text": "Neither then does the end of man lie in these things, nor yet that which aids to the accomplishment of this end, and that which aids toward this end is that which is good.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-143-752661625",
    "text": "Such as are thy habitual thoughts, such also will be the character of thy mind; for the soul is dyed by the thoughts.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-143-3377465687",
    "text": "Dye it then with a continuous series of such thoughts as these: for instance, that where a man can live, there he can also live well.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-148-1115842082",
    "text": "Nothing happens to any man which he is not formed by nature to bear.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-148-50635824",
    "text": "The same things happen to another, and either because he does not see that they have happened, or because he would show a great spirit, he is firm and remains unharmed.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-150-4062195959",
    "text": "In one respect man is the nearest thing to me, so far as I must do good to men and endure them.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-154-271258476",
    "text": "Often think of the rapidity with which things pass by and disappear, both the things which are and the things which are produced.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-158-419013134",
    "text": "I now have what the universal nature now wills me to have; and I do what my nature now wills me to do.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-V-162-3729746178",
    "text": "Well then, and thou hast reason: by thy rational faculty stir up his rational faculty; show him his error, admonish him.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book V, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_V",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-109-3600280254",
    "text": "All existing things soon change, and they will either be reduced to vapor, if indeed all substance is one, or they will be dispersed.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-111-4117606728",
    "text": "The reason which governs knows what its own disposition is, and what it does, and on what material it works.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-127-3664715980",
    "text": "Motions and changes are continually renewing the world, just as the uninterrupted course of time is always renewing the infinite duration of ages.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-128-2027434061",
    "text": "In this flowing stream then, on which there is no abiding, what is there of the things which hurry by on which a man would set a high price?",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-128-3433920583",
    "text": "Something of this kind is the very life of every man, like the exhalation of the blood and the respiration of the air.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-133-3936680833",
    "text": "Of necessity a man must be altogether in a state of perturbation who wants any of these things; and besides, he must often find fault with the gods.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-138-3621750065",
    "text": "In the gymnastic exercises suppose that a man has torn thee with his nails, and by dashing against thy head has inflicted a wound.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-139-673011995",
    "text": "Something like this let thy behavior be in all the other parts of life; let us overlook many things in those who are like antagonists in the gymnasium.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-142-3019691072",
    "text": "I do my duty: other things trouble me not; for they are either things without life, or things without reason, or things that have rambled and know not the way.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-143-1174630020",
    "text": "As to the animals which have no reason, and generally all things and objects, do thou, since thou hast reason and they have none, make use of them with a generous and liberal spirit.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-146-1971748021",
    "text": "Just so then in this life also remember that every duty is made up of certain parts.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-148-1722051763",
    "text": "How cruel it is not to allow men to strive After the things which appear to them to be suitable to their nature and profitable!",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-152-1769758953",
    "text": "Take care that thou art not made into a Caesar, that thou art not dyed with this dye; for such things happen.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-152-3533604686",
    "text": "Keep thyself then simple, good, pure, serious, free from affectation, a friend of justice, a worshipper of the gods, kind, affectionate, strenuous in all proper acts.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-152-2796606657",
    "text": "There is only one fruit of this terrene life—a pious disposition and social acts.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-155-443376117",
    "text": "Imitate all this, that thou mayest have as good a conscience, when thy last hour comes, as he had (i.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-158-2762874343",
    "text": "Neither the labor which the hand does nor that of the foot is contrary to nature, so long as the foot does the foot's work and the hand the hand's.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-162-1157420704",
    "text": "Asia, Europe, are corners of the universe; all the sea a drop in the universe; Athos a little clod of the universe: all the present time is a point in eternity.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-162-3071742603",
    "text": "All things come from thence, from that universal ruling power, either directly proceeding or by way of sequence.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-182-3254638287",
    "text": "One thing here is worth a great deal, to pass thy life in truth and justice, with a benevolent disposition even to liars and unjust men.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-184-1093727502",
    "text": "Be not dissatisfied then that thou must live only so many years and not more; for as thou art satisfied with the amount of substance which has been assigned to thee, so be content with the time.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-191-1995038",
    "text": "Accustom thyself to attend carefully to what is said by another, and as much as it is possible, be in the speaker's mind.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-196-1149525123",
    "text": "How many together with whom I came into the world are already gone out of it.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-197-1133378814",
    "text": "Dost thou think that a false opinion has less power than the bile in the jaundiced or the poison in him who is bitten by a mad dog?",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-199-4187469413",
    "text": "No man will hinder thee from living according to the reason of thy own nature: nothing will happen to thee contrary to the reason of the universal nature.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VI-200-3960631822",
    "text": "How soon will time cover all things, and how many it has covered already.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VII-107-2935449684",
    "text": "Look at things again as thou didst use to look at them; for in this consists the recovery of thy life.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VII-115-1158293093",
    "text": "Let not future things disturb thee, for thou wilt come to them, if it shall be necessary, having with thee the same reason which now thou usest for present things.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VII-131-778736929",
    "text": "Dost thou not see then that for thyself also to change is just the same, and equally necessary for the universal nature?",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VII-132-9975399",
    "text": "How many a Chrysippus, how many a Socrates, how many an Epictetus has time already swallowed up!",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VII-133-4196454594",
    "text": "One thing only troubles me, lest I should do something which the constitution of man does not allow, or in the way which it does not allow, or what it does not allow now.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VII-141-3352802220",
    "text": "Think not so much of what thou hast not as of what thou hast: but of the things which thou hast select the best, and then reflect how eagerly they would have been sought, if thou hadst them not.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VII-141-781432809",
    "text": "At the same time, however, take care that thou dost not through being so pleased with them accustom thyself to overvalue them, so as to be disturbed if ever thou shouldst not have them.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VII-142-3028789569",
    "text": "The rational principle which rules has this nature, that it is content with itself when it does what is just, and so secures tranquillity.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VII-154-121031554",
    "text": "From Antisthenes: It is royal to do good and to be abused.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VII-175-1518385040",
    "text": "Look round at the courses of the stars, as if thou wert going along with them; and constantly consider the changes of the elements into one another, for such thoughts purge away the filth of the terrene life.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VII-194-3344993147",
    "text": "The prime principle then in man's constitution is the social.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VII-195-63380489",
    "text": "The third thing in the rational constitution is freedom from error and from deception.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VII-198-2874575060",
    "text": "Love that only which happens to thee and is spun with the thread of thy destiny.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VII-201-342103084",
    "text": "Within is the fountain of good, and it will ever bubble up, if thou wilt ever dig.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VII-204-1305343005",
    "text": "The art of life is more like the wrestler's art than the dancer's, in respect of this, that it should stand ready and firm to meet onsets which are sudden and unexpected.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-119-4061567574",
    "text": "Let no man any longer hear thee finding fault with the court life or with thy own (v.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-120-3461248738",
    "text": "Repentance is a kind of self-reproof for having neglected something useful; but that which is good must be something useful, and the perfect good man should look after it.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-124-2187537828",
    "text": "Constantly, and, if it be possible, on the occasion of every impression on the soul, apply to it the principles of Physic, of Ethic, and of Dialectic.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-127-3286351733",
    "text": "Remember that to change thy opinion and to follow him who corrects thy error is as consistent with freedom as it is to persist in thy error.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-132-531121427",
    "text": "Nature has had regard in everything no less to the end than to the beginning and the continuance, just like the man who throws up a ball.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-142-4110238669",
    "text": "Such as bathing appears to thee,—oil, sweat, dirt, filthy water, all things disgusting,—so is every part of life and everything.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-144-4145408216",
    "text": "Some indeed have not been remembered even for a short time, and others have become the heroes of fables, and again others have disappeared even from fables.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-150-656672144",
    "text": "Speak both in the senate and to every man, whoever he may be, appropriately, not with any affectation: use plain discourse.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-153-722228287",
    "text": "Nothing will stand in the way of thy acting justly and soberly and considerately.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-159-3409236950",
    "text": "Do not disturb thyself by thinking of the whole of thy life.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-165-421744944",
    "text": "In the constitution of the rational animal I see no virtue which is opposed to justice; but I see a virtue which is opposed to love of pleasure, and that is temperance.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-169-3959420739",
    "text": "The things however which are proper to the understanding no other man is used to impede, for neither fire, nor iron, nor tyrant, nor abuse, touches it in any way.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-177-403598634",
    "text": "—But it is not worth while to live, if this cannot be done.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-177-1034216913",
    "text": "—Take thy departure then from life contentedly, just as he dies who is in full activity, and well pleased too with the things which are obstacles.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-178-2543904457",
    "text": "Remember that the ruling faculty is invincible, when self-collected it is satisfied with itself, if it does nothing which it does not choose to do, even if it resist from mere obstinacy.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-178-1897486441",
    "text": "Therefore the mind which is free from passions is a citadel, for man has nothing more secure to which he can fly for refuge and for the future be inexpugnable.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-182-771784569",
    "text": "Do not add, And why were such things made in the world?",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-189-1050886961",
    "text": "Dost thou wish to be praised by a man who curses himself thrice every hour?",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-189-2019014910",
    "text": "wouldst thou wish to please a man who does not please himself?",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-189-312787712",
    "text": "Does a man please himself who repents of nearly everything that he does?",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-VIII-199-3936782692",
    "text": "The mind indeed, both when it exercises caution and when it is employed about inquiry, moves straight onward not the less, and to its object.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book VIII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_VIII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-111-3520804470",
    "text": "However, to breathe out one's life when a man has had enough of these things is the next best voyage, as the saying is.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-123-1670372479",
    "text": "Wipe out imagination; check desire: extinguish appetite: keep the ruling faculty in its own power.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-127-21740895",
    "text": "Accordingly, then, everything also which participates in the common intelligent nature moves in like manner towards that which is of the same kind with itself, or moves even more.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-130-1675583554",
    "text": "See, then, what now takes place; for only intelligent animals have now forgotten this mutual desire and inclination, and in them alone the property of flowing together is not seen.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-132-998198249",
    "text": "Both man and God and the universe produce fruit; at the proper seasons each produces it.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-132-1130487715",
    "text": "Reason produces fruit both for all and for itself, and there are produced from it other things of the same kind as reason itself.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-134-3644941818",
    "text": "Labor not as one who is wretched, nor yet as one who would be pitied or admired; but direct thy will to one thing only—to put thyself in motion and to check thyself, as the social reason requires.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-137-2484256806",
    "text": "All things are the same, familiar in experience, and ephemeral in time, and worthless in the matter.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-137-3595188078",
    "text": "Everything now is just as it was in the time of those whom we have buried.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-144-1256821051",
    "text": "Penetrate inwards into men's leading principles, and thou wilt see what judges thou art afraid of, and what kind of judges they are of themselves.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-145-3827348133",
    "text": "All things are changing: and thou thyself art in continuous mutation and in a manner in continuous destruction, and the whole universe too.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-149-3248328735",
    "text": "In like manner, then, neither are the termination and cessation and change of thy whole life a thing to be afraid of.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-151-2086495684",
    "text": "As thou thyself art a component part of a social system, so let every act of thine be a component part of social life.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-156-2547633455",
    "text": "However, thou must be well disposed towards them, for by nature they are friends.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-159-2462663808",
    "text": "Soon will the earth cover us all: then the earth, too, will change, and the things also which result from change will continue to change forever, and these again forever.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-171-3694495282",
    "text": "Enough of this wretched life and murmuring and apish tricks.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-176-3847135748",
    "text": "Well, then, is it not better to use what is in thy power like a free man than to desire in a slavish and abject way what is not in thy power?",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-177-3706717608",
    "text": "Do thou pray thus: How shall I not desire to lie with her?",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-177-582713179",
    "text": "In fine, turn thy prayers this way, and see what comes.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-181-4125326028",
    "text": "Let the same considerations be present to thy mind in the case of the knave, and the faithless man, and of every man who does wrong in any way.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-184-942851701",
    "text": "Consider whether thou shouldst not rather blame thyself, because thou didst not expect such a man to err in such a way.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-IX-186-859695163",
    "text": "art thou not content that thou hast done something conformable to thy nature, and dost thou seek to be paid for it?",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book IX, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_IX",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-X-107-771487235",
    "text": "Everything which happens either happens in such wise as thou art formed by nature to bear it, or as thou art not formed by nature to bear it.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book X, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_X",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-X-107-3813304709",
    "text": "If, then, it happens to thee in such way as thou art formed by nature to bear it, do not complain, but bear it as thou art formed by nature to bear it.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book X, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_X",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-X-116-2634064969",
    "text": "The parts of the whole, everything, I mean, which is naturally comprehended in the universe, must of necessity perish; but let this be understood in this sense, that they must undergo change.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book X, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_X",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-X-123-4168901498",
    "text": "If, then, thou maintainest thyself in the possession of these names, without desiring to be called by these names by others, thou wilt be another person and wilt enter on another life.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book X, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_X",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-X-139-863375628",
    "text": "No longer talk at all about the kind of man that a good man ought to be, but be such.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book X, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_X",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-X-140-2582094957",
    "text": "Constantly contemplate the whole of time and the whole of substance, and consider that all individual things as to substance are a grain of a fig, and as to time the turning of a gimlet.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book X, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_X",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-X-143-3216757321",
    "text": "Consider what men are when they are eating, sleeping, generating, easing themselves, and so forth.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book X, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_X",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-X-152-2032162165",
    "text": "A man deposits seed in a womb and goes away, and then another cause takes it and labors on it, and makes a child.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book X, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_X",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-X-153-2865253849",
    "text": "Again, the child passes food down through the throat, and then another cause takes it and makes perception and motion, and in fine, life and strength and other things; how many and how strange!",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book X, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_X",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-X-153-2700372726",
    "text": "Observe then the things which are produced in such a hidden way, and see the power, just as we see the power which carries things downwards and upwards, not with the eyes, but still no less plainly (vii.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book X, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_X",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-X-154-1055490277",
    "text": "Constantly consider how all things such as they now are, in time past also were; and consider that they will be the same again.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book X, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_X",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-X-155-2706885904",
    "text": "Imagine every man who is grieved at anything or discontented to be like a pig which is sacrificed and kicks and screams.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book X, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_X",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-X-160-2014131096",
    "text": "or, if thou art able, take away from him the compulsion.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book X, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_X",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-X-168-1713950903",
    "text": "Place before thy eyes this facility with which the reason will be carried through all things, as fire upwards, as a stone downwards, as a cylinder down an inclined surface, and seek for nothing further.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book X, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_X",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-X-176-1021431595",
    "text": "A little time, and thou shalt close thy eyes; and him who has attended thee to thy grave another soon will lament.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book X, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_X",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-X-182-2311185541",
    "text": "Well, I am separated as from kinsmen, not however dragged resisting, but without compulsion; for this, too, is one of the things according to nature.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book X, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_X",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-X-183-1533864664",
    "text": "Accustom thyself as much as possible on the occasion of anything being done by any person to inquire with thyself, For what object is this man doing this?",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book X, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_X",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-X-184-3423623702",
    "text": "Remember that this which pulls the strings is the thing which is hidden within: this is the power of persuasion, this is life, this, if one may so say, is man.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book X, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_X",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XI-109-3342800060",
    "text": "In all things, then, except virtue and the acts of virtue, remember to apply thyself to their several parts, and by this division to come to value them little: and apply this rule also to thy whole life.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XI-132-2046215652",
    "text": "How plain does it appear that there is not another condition of life so well suited for philosophizing as this in which thou now happenest to be.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XI-138-3368905109",
    "text": "There is no nature which is inferior to art, for the arts imitate the natures of things.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XI-140-1074734197",
    "text": "Let then thy judgment about them be at rest, and they will remain quiet, and thou wilt not be seen either pursuing or avoiding.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XI-145-213978057",
    "text": "How unsound and insincere is he who says, I have determined to deal with thee in a fair way!",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XI-147-3252110607",
    "text": "As to living in the best way, this power is in the soul, if it be indifferent to things which are indifferent.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XI-153-3612839275",
    "text": "Third, that if men do rightly what they do, we ought not to be displeased: but if they do not right, it is plain that they do so involuntarily and in ignorance.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XI-153-982809786",
    "text": "Accordingly men are pained when they are called unjust, ungrateful, and greedy, and in a word wrong-doers to their neighbors (vii.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XI-155-3198174937",
    "text": "Fifth, consider that thou dost not even understand whether men are doing wrong or not, for many things are done with a certain reference to circumstances.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XI-158-900593731",
    "text": "Seventh, that it is not men's acts which disturb us, for those acts have their foundation in men's ruling principles, but it is our own opinions which disturb us.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XI-161-569455723",
    "text": "Ninth, consider that a good disposition is invincible if it be genuine, and not an affected smile and acting a part.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XI-162-2912863619",
    "text": "—And show him with gentle tact and by general principles that this is so, and that even bees do not do as he does, nor any animals which are formed by nature to be gregarious.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XI-164-2056717068",
    "text": "Remember these nine rules, as if thou hadst received them as a gift from the Muses, and begin at last to be a man while thou livest.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XI-200-2018355084",
    "text": "—\"No word is a word of bad omen,\" said Epictetus, \"which expresses any work of nature; or if it is so, it is also a word of bad omen to speak of the ears of corn being reaped\" (Epictetus, iii.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XI, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XI",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XII-104-1654807162",
    "text": "Conformably to piety that thou mayest be content with the lot which is assigned to thee, for nature designed it for thee and thee for it.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XII-105-1395771138",
    "text": "Conformably to justice, that thou mayst always speak the truth freely and without disguise, and do the things which are agreeable to law and according to the worth of each.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XII-113-3167046389",
    "text": "I have often wondered how it is that every man loves himself more than all the rest of men, but yet sets less value on his own opinion of himself than on the opinion of others.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XII-127-1967183928",
    "text": "With respect to that which happens conformably to nature, we ought to blame neither gods, for they do nothing wrong either voluntarily or involuntarily, nor men, for they do nothing wrong except involuntarily.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XII-129-2578572263",
    "text": "How ridiculous and what a stranger he is who is surprised at anything which happens in life.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XII-137-3261898649",
    "text": "In everything always observe what the thing is which produces for thee an appearance, and resolve it by dividing it into the formal, the material, the purpose, and the time within which it must end.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XII-155-298400038",
    "text": "The safety of life is this, to examine everything all through, what it is itself, that is its material, what the formal part; with all thy soul to do justice and to say the truth.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XII-158-3020070781",
    "text": "Well, dost thou wish to have sensation, movement, growth, and then again to cease to grow, to use thy speech, to think?",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XII-159-4021638224",
    "text": "How small a part of the boundless and unfathomable time is assigned to every man, for it is very soon swallowed up in the eternal!",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "meditations-XII-159-571343624",
    "text": "Reflecting on all this, consider nothing to be great, except to act as thy nature leads thee, and to endure that which the common nature brings.",
    "author": "Marcus Aurelius",
    "source": "Meditations, Book XII, translated by George Long",
    "url": "https://en.wikisource.org/wiki/The_Thoughts_of_the_Emperor_Marcus_Aurelius_Antoninus/Book_XII",
    "topics": [
      "Learning",
      "Life"
    ]
  },
  {
    "id": "gitanjali-1-103",
    "text": "Thou hast made me endless, such is thy pleasure. This frail vessel thou emptiest again and again, and fillest it ever with fresh life.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 1, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/1",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-1-104",
    "text": "This little flute of a reed thou hast carried over hills and dales, and hast breathed through it melodies eternally new.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 1, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/1",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-1-106",
    "text": "At the immortal touch of thy hands my little heart loses its limits in joy and gives birth to utterance ineffable.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 1, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/1",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-1-108",
    "text": "Thy infinite gifts come to me only on these very small hands of mine. Ages pass, and still thou pourest, and still there is room to fill.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 1, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/1",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-3-104",
    "text": "I know not how thou singest, my master! I ever listen in silent amazement.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 3, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/3",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-3-106",
    "text": "The light of thy music illumines the world. The life breath of thy music runs from sky to sky. The holy stream of thy music breaks through all stony obstacles and rushes on.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 3, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/3",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-3-107",
    "text": "My heart longs to join in thy song, but vainly struggles for a voice. I would speak, but speech breaks not into song, and I cry out baffled. Ah, thou hast made my heart captive in the endless meshes of thy music, my master!",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 3, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/3",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-4-103",
    "text": "Life of my life, I shall ever try to keep my body pure, knowing that thy living touch is upon all my limbs.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 4, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/4",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-4-104",
    "text": "I shall ever try to keep all untruths out from my thoughts, knowing that thou art that truth which has kindled the light of reason in my mind.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 4, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/4",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-4-106",
    "text": "I shall ever try to drive all evils away from my heart and keep my love in flower, knowing that thou hast thy seat in the inmost shrine of my heart.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 4, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/4",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-4-108",
    "text": "And it shall be my endeavour to reveal thee in my actions, knowing it is thy power gives me strength to act.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 4, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/4",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-6-103",
    "text": "Pluck this little flower and take it, delay not! I fear lest it droop and drop into the dust.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 6, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/6",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-6-104",
    "text": "It may not find a place in thy garland, but honour it with a touch of pain from thy hand and pluck it. I fear lest the day end before I am aware, and the time of offering go by.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 6, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/6",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-6-106",
    "text": "Though its colour be not deep and its smell be faint, use this flower in thy service and pluck it while there is time.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 6, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/6",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-7-104",
    "text": "My song has put off her adornments. She has no pride of dress and decoration. Ornaments would mar our union; they would come between thee and me; their jingling would drown thy whispers.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 7, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/7",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-7-106",
    "text": "My poet's vanity dies in shame before thy sight. O master poet, I have sat down at thy feet. Only let me make my life simple and straight, like a flute of reed for thee to fill with music.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 7, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/7",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-9-104",
    "text": "Leave all thy burdens on his hands who can bear all, and never look behind in regret.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 9, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/9",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-9-106",
    "text": "Thy desire at once puts out the light from the lamp it touches with its breath. It is unholy—take not thy gifts through its unclean hands. Accept only what is offered by sacred love.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 9, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/9",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-10-103",
    "text": "Here is thy footstool and there rest thy feet where live the poorest, and lowliest, and lost.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 10, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/10",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-10-106",
    "text": "Pride can never approach to where thou walkest in the clothes of the humble among the poorest, and lowliest, and lost.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 10, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/10",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-10-108",
    "text": "My heart can never find its way to where thou keepest company with the companionless among the poorest, the lowliest, and the lost.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 10, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/10",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-12-103",
    "text": "The time that my journey takes is long and the way of it long.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 12, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/12",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-12-104",
    "text": "I came out on the chariot of the first gleam of light, and pursued my voyage through the wildernesses of worlds leaving my track on many a star and planet.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 12, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/12",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-12-106",
    "text": "It is the most distant course that comes nearest to thyself, and that training is the most intricate which leads to the utter simplicity of a tune.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 12, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/12",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-12-108",
    "text": "The traveller has to knock at every alien door to come to his own, and one has to wander through all the outer worlds to reach the innermost shrine at the end.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 12, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/12",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-18-104",
    "text": "Clouds heap upon clouds and it darkens. Ah, love, why dost thou let me wait outside at the door all alone?",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 18, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/18",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-18-106",
    "text": "In the busy moments of the noontide work I am with the crowd, but on this dark lonely day it is only for thee that I hope.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 18, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/18",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-18-108",
    "text": "If thou showest me not thy face, if thou leavest me wholly aside, I know not how I am to pass these long, rainy hours.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 18, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/18",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-18-110",
    "text": "I keep gazing on the far away gloom of the sky, and my heart wanders wailing with the restless wind.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 18, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/18",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-19-102",
    "text": "If thou speakest not I will fill my heart with thy silence and endure it. I will keep still and wait like the night  with starry vigil and its head bent low with patience.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 19, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/19",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-19-104",
    "text": "The morning will surely come, the darkness will vanish, and thy voice pour down in golden streams breaking through the sky.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 19, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/19",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-19-106",
    "text": "Then thy words will take wing in songs from every one of my birds' nests, and thy melodies will break forth in flowers in all my forest groves.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 19, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/19",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-21-103",
    "text": "I must launch out my boat. The languid hours pass by on the shore—Alas for me!",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 21, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/21",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-21-104",
    "text": "The spring has done its flowering and taken leave. And now with the burden of faded futile flowers I wait and linger.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 21, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/21",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-21-106",
    "text": "The waves have become clamorous, and upon the bank in the shady lane the yellow leaves flutter and fall.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 21, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/21",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-21-108",
    "text": "What emptiness do you gaze upon! Do you not feel a thrill passing through the air with the notes of the far away song floating from the other shore?",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 21, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/21",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-23-103",
    "text": "Art thou abroad on this stormy night on thy journey of love, my friend? The sky groans like one in despair.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 23, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/23",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-23-104",
    "text": "I have no sleep to-night. Ever and  again I open my door and look out on the darkness, my friend!",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 23, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/23",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-23-106",
    "text": "I can see nothing before me. I wonder where lies thy path!",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 23, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/23",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-23-108",
    "text": "By what dim shore of the ink-black river, by what far edge of the frowning forest, through what mazy depth of gloom art thou threading thy course to come to me, my friend?",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 23, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/23",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-27-103",
    "text": "Light, oh where is the light? Kindle it with the burning fire of desire!",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 27, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/27",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-27-108",
    "text": "The sky is overcast with clouds and the rain is ceaseless. I know not what this is that stirs in me,—I know not its meaning.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 27, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/27",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-27-109",
    "text": "A moment's flash of lightning drags down a deeper gloom on my sight, and my heart gropes for the path to where the music of the night calls me.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 27, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/27",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-36-103",
    "text": "This is my prayer to thee, my lord—strike, strike at the root of penury in my heart.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 36, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/36",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-36-104",
    "text": "Give me the strength lightly to bear my joys and sorrows.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 36, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/36",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-36-106",
    "text": "Give me the strength to make my love fruitful in service.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 36, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/36",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-36-108",
    "text": "Give me the strength never to disown the poor or bend my knees before insolent might.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 36, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/36",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-36-110",
    "text": "Give me the strength to raise my mind high above daily trifles.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 36, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/36",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-36-112",
    "text": "And give me the strength to surrender my strength to thy will with love.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 36, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/36",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-39-104",
    "text": "When the heart is hard and parched up, come upon me with a shower of mercy.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 39, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/39",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-39-106",
    "text": "When grace is lost from life, come with a burst of song.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 39, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/39",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-39-108",
    "text": "When tumultuous work raises its din on all sides shutting me out from beyond, come to me, my lord of silence, with thy peace and rest.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 39, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/39",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-39-110",
    "text": "When my beggarly heart sits crouched, shut up in a corner, break open the door,  my king, and come with the ceremony of a king.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 39, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/39",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-39-111",
    "text": "When desire blinds the mind with delusion and dust, O thou holy one, thou wakeful, come with thy light and thy thunder.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 39, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/39",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-40-102",
    "text": "The rain has held back for days and days, my God, in my arid heart. The horizon is fiercely naked—not the thinnest cover of a soft cloud, not the vaguest hint of a distant cool shower.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 40, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/40",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-40-106",
    "text": "But call back, my lord, call back this pervading silent heat, still and keen and cruel, burning the heart with dire despair.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 40, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/40",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-40-107",
    "text": "Let the cloud of grace bend low from  above like the tearful look of the mother on the day of the father's wrath.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 40, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/40",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-43-102",
    "text": "The day was when I did not keep myself in readiness for thee; and entering my heart unbidden even as one of the common crowd, unknown to me, my king, thou didst press the signet of eternity upon many a fleeting moment of my life.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 43, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/43",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-43-104",
    "text": "And to-day when by chance I light upon them and see thy signature, I find they have lain scattered in the dust mixed with the memory of joys and sorrows of my trivial days forgotten.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 43, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/43",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-43-105",
    "text": "Thou didst not turn in contempt from my childish play among dust, and the steps that I heard in my playroom are the same that are echoing from star to star.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 43, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/43",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-45-103",
    "text": "Have you not heard his silent steps? He comes, comes, ever comes.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 45, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/45",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-45-104",
    "text": "Every moment and every age, every day and every night he comes, comes, ever comes.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 45, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/45",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-45-108",
    "text": "In the fragrant days of sunny April through the forest path he comes, comes, ever comes.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 45, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/45",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-45-110",
    "text": "In the rainy gloom of July nights on the thundering chariot of clouds he comes, comes, ever comes.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 45, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/45",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-45-111",
    "text": "In sorrow after sorrow it is his steps that press upon my heart, and it is the golden touch of his feet that makes my joy to shine.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 45, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/45",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-46-103",
    "text": "I know not from what distant time thou art ever coming nearer to meet me. Thy sun and stars can never keep thee hidden from me for aye.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 46, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/46",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-46-104",
    "text": "In many a morning and eve thy footsteps have been heard and thy messenger has come within my heart and called me in secret.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 46, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/46",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-46-106",
    "text": "I know not why to-day my life is all astir, and a feeling of tremulous joy is passing through my heart.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 46, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/46",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-46-108",
    "text": "It is as if the time were come to wind up my work, and I feel in the air a faint smell of thy sweet presence.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 46, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/46",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-47-102",
    "text": "The night is nearly spent waiting for him in vain. I fear lest in the morning he suddenly come to my door when I have fallen asleep wearied out. Oh friends, leave the way open to him—forbid him not.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 47, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/47",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-47-105",
    "text": "Ah, my sleep, precious sleep, which only waits for his touch to vanish. Ah, my closed eyes that would open their lids only to the light of his smile when he stands before me like a dream emerging from darkness of sleep.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 47, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/47",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-47-107",
    "text": "Let him appear before my sight as the first of all lights and all forms. The first thrill of joy to my awakened soul let it come from his glance. And let my return to myself be immediate return to him.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 47, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/47",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-49-103",
    "text": "You came down from your throne and stood at my cottage door.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 49, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/49",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-49-104",
    "text": "I was singing all alone in a corner, and the melody caught your ear. You came down and stood at my cottage door.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 49, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/49",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-53-105",
    "text": "Beautiful is thy wristlet, decked with starry gems; but thy sword, O lord of thunder, is wrought with uttermost beauty, terrible to behold or to think of.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 53, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/53",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-56-102",
    "text": "Thus it is that thy joy in me is so full. Thus it is that thou hast come down to me. O thou lord of all heavens, where would be thy love if I were not?",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 56, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/56",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-56-104",
    "text": "Thou hast taken me as thy partner of all this wealth. In my heart is the endless play of thy delight. In my life thy will is ever taking shape.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 56, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/56",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-56-105",
    "text": "And for this, thou who art the King  of kings hast decked thyself in beauty to captivate my heart. And for this thy love loses itself in the love of thy lover, and there art thou seen in the perfect union of two.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 56, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/56",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-63-102",
    "text": "Thou hast made me known to friends whom I knew not. Thou hast given me seats in homes not my own. Thou hast brought the distant near and made a brother of the stranger.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 63, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/63",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-63-104",
    "text": "I am uneasy at heart when I have to leave my accustomed shelter; I forget that there abides the old in the new, and that there also thou abidest.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 63, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/63",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-63-107",
    "text": "When one knows thee, then alien there is none, then no door is shut. Oh, grant me my prayer that I may never lose the bliss of the touch of the one in the play of the many.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 63, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/63",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-70-103",
    "text": "Is it beyond thee to be glad with the gladness of this rhythm? to be tossed and lost and broken in the whirl of this fearful joy?",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 70, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/70",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-70-104",
    "text": "All things rush on, they stop not, they look not behind, no power can hold them back, they rush on.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 70, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/70",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-70-106",
    "text": "Keeping steps with that restless, rapid music, seasons come dancing and pass away—colours, tunes, and perfumes pour in endless cascades in the abounding joy that scatters and gives up and dies every moment.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 70, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/70",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-72-103",
    "text": "He it is, the innermost one, who awakens my being with his deep hidden touches.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 72, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/72",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-72-104",
    "text": "He it is who puts his enchantment upon these eyes and joyfully plays on the chords of my heart in varied cadence of pleasure and pain.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 72, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/72",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-72-106",
    "text": "He it is who weaves the web of this maya in evanescent hues of gold and silver, blue and green, and lets peep out through the folds his feet, at whose touch I forget myself.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 72, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/72",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-72-108",
    "text": "Days come and ages pass, and it is ever he who moves my heart in many a  name, in many a guise, in many a rapture of joy and of sorrow.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 72, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/72",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-80-102",
    "text": "I am like a remnant of a cloud of autumn uselessly roaming in the sky, O my sun ever-glorious! Thy touch has not yet melted my vapour, making me one with thy light, and thus I count months and years separated from thee.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 80, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/80",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-80-104",
    "text": "If this be thy wish and if this be thy  play, then take this fleeting emptiness of mine, paint it with colours, gild it with gold, float it on the wanton wind and spread it in varied wonders.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 80, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/80",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-80-105",
    "text": "And again when it shall be thy wish to end this play at night, I shall melt and vanish away in the dark, or it may be in a smile of the white morning, in a coolness of purity transparent.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 80, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/80",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-83-103",
    "text": "Mother, I shall weave a chain of pearls for thy neck with my tears of sorrow.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 83, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/83",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-83-104",
    "text": "The stars have wrought their anklets of light to deck thy feet, but mine will hang upon thy breast.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 83, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/83",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-83-106",
    "text": "Wealth and fame come from thee and it is for thee to give or to withhold them. But this my sorrow is absolutely mine own, and when I bring it to thee as my offering thou rewardest me with thy grace.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 83, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/83",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-85-103",
    "text": "When the warriors came out first from their master's hall, where had they hid their power? Where were their armour and their arms?",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 85, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/85",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-85-104",
    "text": "They looked poor and helpless, and the arrows were showered upon them on the day they came out from their master's hall.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 85, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/85",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-85-106",
    "text": "When the warriors marched back again to their master's hall where did they hide their power?",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 85, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/85",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-85-108",
    "text": "They had dropped the sword and dropped the bow and the arrow; peace was on their foreheads, and they had left the fruits of their life behind them  on the day they marched back again to their master's hall.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 85, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/85",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-86-104",
    "text": "The night is dark and my heart is fearful—yet I will take up the lamp, open my gates and bow to him my welcome. It is thy messenger who stands at my door.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 86, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/86",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-86-106",
    "text": "I will worship him with folded hands, and with tears. I will worship him placing at his feet the treasure of my heart.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 86, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/86",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-86-108",
    "text": "He will go back with his errand done, leaving a dark shadow on my morning; and in my desolate home only my forlorn self will remain as my last offering to thee.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 86, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/86",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-88-102",
    "text": "Deity of the ruined temple! The broken strings of Vina sing no more your praise. The bells in the evening proclaim not your time of worship. The air is still and silent about you.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 88, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/88",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-88-104",
    "text": "In your desolate dwelling comes the vagrant spring breeze. It brings the tidings of flowers—the flowers that for your worship are offered no more.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 88, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/88",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-88-105",
    "text": "Your worshipper of old wanders ever longing for favour still refused. In the eventide, when fires and shadows mingle with the gloom of dust, he wearily comes back to the ruined temple with hunger in his heart.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 88, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/88",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-88-107",
    "text": "Many a festival day comes to you in silence, deity of the ruined temple. Many a night of worship goes away with lamp unlit.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 88, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/88",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-88-109",
    "text": "Many new images are built by masters of cunning art and carried to  the holy stream of oblivion when their time is come.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 88, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/88",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-88-110",
    "text": "Only the deity of the ruined temple remains unworshipped in deathless neglect.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 88, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/88",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-90-104",
    "text": "Oh, I will set before my guest the full vessel of my life—I will never let him go with empty hands.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 90, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/90",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-91-104",
    "text": "Day after day have I kept watch for  thee; for thee have I borne the joys and pangs of life.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 91, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/91",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-91-106",
    "text": "All that I am, that I have, that I hope and all my love have ever flowed towards thee in depth of secrecy. One final glance from thine eyes and my life will be ever thine own.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 91, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/91",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-91-108",
    "text": "The flowers have been woven and the garland is ready for the bridegroom. After the wedding the bride shall leave her home and meet her lord alone in the solitude of night.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 91, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/91",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-92-102",
    "text": "I know that the day will come when my sight of this earth shall be lost, and life will take its leave in silence, drawing the last curtain over my eyes.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 92, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/92",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-92-104",
    "text": "Yet stars will watch at night, and morning rise as before, and hours heave like sea waves casting up pleasures and pains.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 92, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/92",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-92-107",
    "text": "Things that I longed for in vain and things that I got—let them pass. Let me but truly possess the things that I ever spurned and overlooked.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 92, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/92",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-94-103",
    "text": "At this time of my parting, wish me good luck, my friends! The sky is flushed with the dawn and my path lies beautiful.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 94, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/94",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-94-104",
    "text": "Ask not what I have with me to take there. I start on my journey with empty hands and expectant heart.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 94, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/94",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-94-106",
    "text": "I shall put on my wedding garland. Mine is not the red-brown dress of the traveller, and though there are dangers on the way I have no fear in my mind.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 94, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/94",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-94-108",
    "text": "The evening star will come out when my voyage is done and the plaintive notes of the twilight melodies be struck up from the King's gateway.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 94, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/94",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-96-103",
    "text": "When I go from hence let this be my parting word, that what I have seen is unsurpassable.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 96, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/96",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-96-104",
    "text": "I have tasted of the hidden honey of this lotus that expands on the ocean of light, and thus am I blessed—let this be my parting word.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 96, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/96",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-96-106",
    "text": "In this playhouse of infinite forms I have had my play and here have I caught sight of him that is formless.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 96, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/96",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-96-108",
    "text": "My whole body and my limbs have thrilled with his touch who is beyond touch; and if the end comes here, let it come—let this be my parting word.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 96, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/96",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-101-102",
    "text": "Ever in my life have I sought thee with my songs. It was they who led me from door to door, and with them have I felt about me, searching and touching my world.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 101, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/101",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-101-104",
    "text": "It was my songs that taught me all the lessons I ever learnt; they showed me secret paths, they brought before my sight many a star on the horizon of my heart.",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 101, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/101",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "gitanjali-101-106",
    "text": "They guided me all the day long to the mysteries of the country of pleasure and pain, and, at last, to what palace gate have they brought me in the evening at the end of my journey?",
    "author": "Rabindranath Tagore",
    "source": "Gitanjali, poem 101, translated by the author",
    "url": "https://en.wikisource.org/wiki/Gitanjali/101",
    "topics": [
      "Books",
      "Life"
    ]
  },
  {
    "id": "nietzsche-bge-63",
    "text": "He who is a thorough teacher takes things seriously—and even himself—only in relation to his pupils.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 63, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-64",
    "text": "“Knowledge for its own sake”—that is the last snare laid by morality: we are thereby completely entangled in morals once more.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 64, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-65",
    "text": "The charm of knowledge would be small, were it not that so much shame has to be overcome on the way to it.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 65, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-68",
    "text": "“I did that,” says my memory. “I could not have done that,” says my pride, and remains inexorable. Eventually—the memory yields.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 68, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-70",
    "text": "If a man has character, he has also his typical experience, which always recurs.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 70, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-71",
    "text": "The Sage as Astronomer.—So long as thou feelest the stars as an “above thee,” thou lackest the eye of the discerning one.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 71, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-72",
    "text": "It is not the strength, but the duration of great sentiments that makes great men.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 72, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-73",
    "text": "He who attains his ideal, precisely thereby surpasses it.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 73, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-73a",
    "text": "Many a peacock hides his tail from every eye—and cails it his pride.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 73a, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-74",
    "text": "A man of genius is unbearable, unless he possess at least two things besides: gratitude and purity.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 74, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-75",
    "text": "The degree and nature of a man’s sensuality extends to the highest altitudes of his spirit.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 75, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-76",
    "text": "Under peaceful conditions the militant man attacks himself.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 76, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-77",
    "text": "With his principles a man seeks either to dominate, or justify, or honour, or reproach, or conceal his habits: two men with the same principles probably seek fundamentally different ends therewith.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 77, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-78",
    "text": "He who despises himself, nevertheless esteems himself thereby, as a despiser.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 78, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-79",
    "text": "A soul which knows that it is loved, but does not itself love, betrays its sediment: its dregs come up.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 79, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-82",
    "text": "“Sympathy for all”—would be harshness and tyranny for thee, my good neighbour!",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 82, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-83",
    "text": "Instinct.—When the house is on fire one forgets even the dinner—Yes, but one recovers it from amongst the ashes.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 83, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-88",
    "text": "One begins to distrust very clever persons when they become embarrassed.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 88, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-89",
    "text": "Dreadful experiences raise the question whether he who experiences them is not something dreadful also.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 89, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-90",
    "text": "Heavy, melancholy men turn lighter, and come temporarily to their surface, precisely by that which makes others heavy—by hatred and love.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 90, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-91",
    "text": "So cold, so icy, that one burns one’s finger at the touch of him! Every hand that lays hold of him shrinks back!—And for that very reason many think him red-hot.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 91, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-92",
    "text": "Who has not, at one time or another—sacrificed himself for the sake of his good name?",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 92, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-93",
    "text": "In affability there is no hatred of men, but precisely on that account a great deal too much contempt of men.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 93, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-94",
    "text": "The maturity of man—that means, to have reacquired the seriousness that one had as a child at play.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 94, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-95",
    "text": "To be ashamed of one’s immorality is a step on the ladder at the end of which one is ashamed also of one’s morality.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 95, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-96",
    "text": "One should part from life as Ulysses parted from Nausicaa—blessing it rather than in love with it.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 96, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-97",
    "text": "What? A great man? I always see merely the play-actor of his own ideal.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 97, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-98",
    "text": "When one trains one’s conscience, it kisses one while it bites.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 98, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-100",
    "text": "We all feign to ourselves that we are simpler than we are; we thus relax ourselves away from our fellows.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 100, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-106",
    "text": "By means of music the very passions enjoy themselves.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 106, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-107",
    "text": "A sign of strong character, when once the resolution has been taken, to shut the ear even to the best counter-arguments. Occasionally, therefore, a will to stupidity.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 107, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-108",
    "text": "There is no such thing as moral phenomena, but only a moral interpretation of phenomena.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 108, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-111",
    "text": "Our vanity is most difficult to wound just when our pride has been wounded.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 111, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-112",
    "text": "To him who feels himself preordained to contemplation and not to belief, all believers are too noisy and obtrusive; he guards against them.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 112, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-116",
    "text": "The great epochs of our life are at the points when we gain courage to rebaptize our badness as the best in us.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 116, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-117",
    "text": "The will to overcome an emotion, is ultimately only the will of another, or of several other, emotions.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 117, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-118",
    "text": "There is an innocence of admiration: it is possessed by him to whom it has not yet occurred that he himself may be admired some day.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 118, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-119",
    "text": "Our loathing of dirt may be so great as to prevent us cleaning ourselves—“justifying” ourselves.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 119, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-120",
    "text": "Sensuality often forces the growth of love too much, so that its root remains weak, and is easily torn up.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 120, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-122",
    "text": "To rejoice on account of praise is in many cases merely politeness of heart—and the very opposite of vanity of spirit.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 122, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-123",
    "text": "Even concubinage has been corrupted—by marriage.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 123, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-124",
    "text": "He who exults at the stake, does not triumph over pain, but because of the fact that he does not feel pain where he expected it. A parable.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 124, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-125",
    "text": "When we have to change an opinion about any one, we charge heavily to his account the inconvenience he thereby causes us.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 125, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-126",
    "text": "A nation is a detour of nature to arrive at six or seven great men.—Yes, and then to get round them.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 126, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-128",
    "text": "The more abstract the truth you wish to teach, the more must you allure the senses to it.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 128, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-130",
    "text": "What person is begins to betray itself when his talent decreases—when he ceases to show what he can do. Talent is also an adornment; an adornment is also a concealment.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 130, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-133",
    "text": "He who cannot find the way to his ideal, lives more frivolously and shamelessly than the man without an ideal.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 133, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-134",
    "text": "From the senses originate all trustworthiness, all good conscience, all evidence of truth.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 134, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-135",
    "text": "Pharisaism is not a deterioration of the good man; a considerable part of it is rather an essential condition of being good.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 135, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-136",
    "text": "The one seeks an accoucheur for his thoughts, the other seeks some one whom he can assist: a good conversation thus originates.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 136, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-138",
    "text": "We do the same when awake as when dreaming; we only invent and imagine him with whom we have intercourse—and forget it immediately.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 138, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-143",
    "text": "Our vanity would like what we do best to pass precisely for what is most difficult to us—Concerning the origin of many systems of morals.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 143, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-146",
    "text": "He who fights with monsters should be careful lest he thereby become a monster. And if thou gaze long into an abyss, the abyss will also gaze into thee.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 146, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-147",
    "text": "From old Florentine novels—moreover, from life: Buona femmina e mala femmina vuol bastone.—Sacchetti, Nov. 86.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 147, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-151",
    "text": "It is not enough to possess a talent: one must also have your permission to possess it;—eh, my friends?",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 151, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-152",
    "text": "“Where there is the tree of knowledge, there is always Paradise:” so say the most ancient and the most modern serpents.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 152, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-154",
    "text": "Objection, evasion, joyous distrust, and love of irony are signs of health; everything absolute belongs to pathology.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 154, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-155",
    "text": "The sense of the tragic increases and declines with sensuousness.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 155, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-156",
    "text": "Insanity in individuals is something rare—but in groups, parties, nations, and epochs it is the rule.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 156, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-157",
    "text": "The thought of suicide is a great consolation: by means of it one gets successfully through many a bad night.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 157, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-158",
    "text": "Not only our reason, but also our conscience, truckles to our strongest impulse—the tyrant in us.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 158, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-159",
    "text": "One must repay good and ill; but why just to the person who did us good or ill?",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 159, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-160",
    "text": "One no longer loves one’s knowledge sufficiently after one has communicated it.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 160, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-161",
    "text": "Poets act shamelessly towards their experiences: they exploit them.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 161, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-162",
    "text": "“Our fellow-creature is not our neighbour, but our neighbour's neighbour:”—so thinks every nation.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 162, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-163",
    "text": "Love brings to light the noble and hidden qualities of a lover—his rare and exceptional traits: it is thus liable to be deceptive as to his normal character.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 163, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-165",
    "text": "In Sight of every Party.—A shepherd has always need of a bell-wether—or he has himself to be a wether occasionally.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 165, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-166",
    "text": "One may indeed lie with the mouth; but with the accompanying grimace one nevertheless tells the truth.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 166, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-167",
    "text": "To vigorous men intimacy is a matter of shame—and something precious.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 167, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-169",
    "text": "To talk much about oneself may also be a means of concealing oneself.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 169, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-170",
    "text": "In praise there is more obtrusiveness than in blame.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 170, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-171",
    "text": "Pity has an almost ludicrous effect on a man of knowledge, like tender hands on a Cyclops.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 171, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-173",
    "text": "One does not hate as long as one disesteems, but only when one esteems equal or superior.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 173, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-174",
    "text": "Ye Utilitarians—ye, too, love the utile only as a vehicle for your inclinations,—ye, too, really find the noise of its wheels insupportable!",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 174, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-175",
    "text": "One loves ultimately one’s desires, not the thing desired.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 175, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-176",
    "text": "The vanity of others is only counter to our taste when it is counter to our vanity.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 176, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-177",
    "text": "With regard to what “truthfulness” is, perhaps nobody has ever been sufficiently truthful.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 177, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-178",
    "text": "One does not believe in the follies of clever men: what a forfeiture of the rights of man!",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 178, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-180",
    "text": "There is an innocence in lying which is the sign of good faith in a cause.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 180, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-181",
    "text": "It is inhuman to bless when one is being cursed.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 181, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-182",
    "text": "The familiarity of superiors embitters one, because it may not be returned.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 182, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-184",
    "text": "There is a haughtiness of kindness which has the appearance of wickedness.",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 184, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  },
  {
    "id": "nietzsche-bge-185",
    "text": "“I dislike him.”—Why?—“I am not a match for him.”—Did any one ever answer so?",
    "author": "Friedrich Nietzsche",
    "source": "Beyond Good and Evil, section 185, translated by Helen Zimmern",
    "url": "https://en.wikisource.org/wiki/Beyond_Good_and_Evil/Chapter_IV",
    "topics": [
      "Books",
      "Learning"
    ]
  }
];
